// Gerado via AI Gateway com base em diretrizes BR/AHA/ESC/SBC/MS 2024-2026
import type { Flashcard } from "./flashcardsData";

export const flashcardsExtra3: Flashcard[] = [
  { id: "fc-gen-cardiologia-001", front: "Quais são os critérios diagnósticos para infarto agudo do miocárdio tipo 1 (IAM tipo 1)?", back: "Diagnóstico de IAM tipo 1 requer detecção de elevação e/ou queda de biomarcadores cardíacos (preferencialmente troponina) com pelo menos um valor acima do percentil 99 do URL (Upper Reference Limit), associada a evidência de isquemia miocárdica aguda, como:\n- Sintomas compatíveis com isquemia miocárdica (dor precordial)\n- Alterações eletrocardiográficas novas (onda Q, infradesnivelamento de ST, supradesnivelamento de ST)\n- Desenvolvimento de onda Q patológica no ECG\n- Alterações de mobilidade parietal segmentar novas em exames de imagem\n- Identificação de trombo intracoronário (angiografia ou autópsia).", category: "cardiologia", tags: ["iam", "diagnóstico", "troponina"] },
  { id: "fc-gen-cardiologia-002", front: "Quais são as doses recomendadas de antiagregação plaquetária dupla (AAS + inibidor P2Y12) para pacientes com SCA sem supra de ST (SCASSST) de alto risco, e qual a duração ideal?", back: "Para SCASSST de alto risco (ex: TIMI Risk Score ≥3 ou GRACE Risk Score >140):\n- AAS: Dose de ataque 150-300 mg (em pacientes não em uso prévio), seguida de 75-100 mg/dia.\n- Ticagrelor: Dose de ataque 180 mg, seguida de 90 mg 2x/dia.\n- Prasugrel: Dose de ataque 60 mg, seguida de 10 mg/dia (contraindicado em AVC/AIT prévio ou peso <60kg/idade >75 a).\n- Clopidogrel: Dose de ataque 300-600 mg, seguida de 75 mg/dia (alternativa se contraindicação aos anteriores).\nDuração ideal: 12 meses, podendo ser encurtada (3-6 meses) ou estendida ( >12 meses) com base no balanço isquemia/sangramento.", category: "cardiologia", tags: ["scasst", "antiagregação", "dapt"] },
  { id: "fc-gen-cardiologia-003", front: "Qual o principal mecanismo de ação dos inibidores da SGLT2 (iSGLT2) na insuficiência cardíaca e quais os efeitos clínicos cardiovasculares esperados?", back: "Mecanismo principal: Inibição do cotransportador de sódio-glicose 2 (SGLT2) nos túbulos renais.\nEfeitos na IC:\n- Aumento da natriurese e diurese osmótica (efeito diurético leve).\n- Redução da pré-carga e pós-carga cardíaca.\n- Melhora da função endotelial e rigidez arterial.\n- Efeitos anti-inflamatórios e antifibróticos.\n- Melhora do metabolismo energético miocárdico.\n- Inibição da via de troca de Na+/H+.\nResultados Dclinicos: Redução de internações por IC, mortalidade cardiovascular e mortalidade por todas as causas, independentemente da presença de diabetes.", category: "cardiologia", tags: ["insuficiência cardíaca", "isglt2", "mecanismo"] },
  { id: "fc-gen-cardiologia-004", front: "Quais as principais indicações e contraindicações para o uso de betabloqueadores em pacientes com insuficiência cardíaca com fração de ejeção reduzida (ICFEr)?", back: "Indicações:\n- Todos os pacientes com ICFEr sintomática (CF II-IV) e estáveis, sem contraindicações.\n- Iniciar em doses baixas e titular lentamente até a dose-alvo ou máxima tolerada.\n- Revaliar após descompensação da IC antes de reinstalar.\nContraindicações absolutas:\n- Asma grave não controlada ou broncoespasmo agudo.\n- Bradiarritmias sintomáticas (ex: BAV de alto grau sem MP).\n- Hipotensão sintomática.\n- Choque cardiogênico.\n- Doença arterial obstrutiva periférica grave sintomática com isquemia crítica.", category: "cardiologia", tags: ["icer", "betabloqueador", "terapêutica"] },
  { id: "fc-gen-cardiologia-005", front: "Quais são os 3 pilares fundamentais da terapia medicamentosa para o tratamento da hipertensão arterial pulmonar (HAP) do grupo 1?", back: "Os 3 pilares fundamentais da terapia medicamentosa para HAP do grupo 1 (baseado nas diretrizes atuais) são:\n1. Antagonistas dos Receptores da Endotelina (AREs): ex. Bosentana, Ambrisentana, Macitentana.\n2. Inibidores da 5-Fosfodiesterase (iPDE-5) ou Estimuladores da Guanilato Ciclase Solúvel (sGC): ex. Sildenafila, Tadalafila (iPDE-5); Riociguat (sGC).\n3. Análogos da Prostaciclina ou Agonistas dos Receptores da Prostaciclina: ex. Epoprostenol, Iloprost, Treprostinil (análogos); Selexipag (agonista).", category: "cardiologia", tags: ["hipertensão pulmonar", "hap", "farmacologia"] },
  { id: "fc-gen-pneumologia-001", front: "Quais os critérios diagnósticos para Síndrome da Angústia Respiratória Aguda (SARA) segundo a definição de Berlim (2012)?", back: "Os critérios diagnósticos da SARA incluem:\n- Tempo: Início recente (até 7 dias) ou piora dos sintomas respiratórios.\n- Imagem: Opacidades bilaterais na imagem (radiografia/tomografia) não totalmente explicadas por derrames, atelectasias ou nódulos.\n- Origem do edema: Edema não totalmente explicado por insuficiência cardíaca ou sobrecarga volêmica (avaliação objetiva, ex: ecocardiograma, se necessário).\n- Oxigenação (PaO2/FiO2 com PEEP ≥ 5 cmH2O):\n  - Leve: 200 < PaO2/FiO2 ≤ 300 mmHg\n  - Moderada: 100 < PaO2/FiO2 ≤ 200 mmHg\n  - Grave: PaO2/FiO2 ≤ 100 mmHg", category: "pneumologia", tags: ["sara", "uti", "ventilação"] },
  { id: "fc-gen-pneumologia-002", front: "Qual a conduta inicial para um paciente com exacerbação grave da Doença Pulmonar Obstrutiva Crônica (DPOC) após oxigenoterapia?", back: "A conduta inicial para exacerbação grave da DPOC, após oxigenoterapia para SpO2 de 88-92%, inclui:\n- Broncodilatadores de curta ação: Salbutamol nebulizado (2,5-5 mg) ou terbutalina (5-10 mg) e brometo de ipratrópio (250-500 mcg) a cada 20 minutos por 1 hora, ou em doses contínuas.\n- Corticosteroide sistêmico: Prednisolona oral (40 mg/dia por 5 dias) ou metilprednisolona IV (60-80 mg/dia por 3 dias, seguido de oral).\n- Antibiótico (se houver indicação: aumento de escarro purulento, volume e/ou dispneia): Amoxicilina/clavulanato, azitromicina ou levofloxacino por 5-7 dias.\n- Considerar VNI (Ventilação Não Invasiva) se acidose respiratória (pH < 7,35 e PaCO2 > 45 mmHg) ou trabalho respiratório intenso.", category: "pneumologia", tags: ["dpoc", "exacerbação", "broncodilatador"] },
  { id: "fc-gen-pneumologia-003", front: "Enumere as classes de anti-hipertensivos pulmonares utilizados no tratamento da Hipertensão Arterial Pulmonar (HAP), com um exemplo de fármaco para cada.", back: "As classes de fármacos para HAP são:\n- Antagonistas do receptor da endotelina (ARE): Bosentana, Ambrisentana, Macitentana.\n- Inibidores da 5-fosfodiesterase (iPDE5): Sildenafila, Tadalafila.\n- Análogos da prostaciclina e agonistas do receptor de prostaciclina: Epoprostenol, Treprostinil, Iloprosta, Selexipague.\n- Ativadores da guanilato ciclase solúvel (AGC): Riociguat.\n- Antagonistas do receptor da prostaciclina (ARP): Não há nesta lista. Seria um erro comum.\n- A indicação de cada fármaco depende da classe funcional (OMS) do paciente e da etiologia da HAP.", category: "pneumologia", tags: ["hap", "hipertensão", "pulmão"] },
  { id: "fc-gen-pneumologia-004", front: "Quais são os principais fatores de risco para Trombose Venosa Profunda (TVP) e consequente Embolia Pulmonar (EP), segundo as diretrizes atuais?", back: "Os principais fatores de risco para TVP/EP são:\n- Cirurgia recente (principalmente ortopédicas de grande porte, abdominais, pélvicas).\n- Trauma grave.\n- Imobilização prolongada (internação, viagens longas).\n- Câncer ativo e quimioterapia.\n- Trombofilias (congênitas ou adquiridas, ex: deficiência de antitrombina III, fator V de Leiden, SAF).\n- Idade avançada (> 60 anos).\n- Obesidade (IMC > 30 kg/m²).\n- Gravidez e puerpério.\n- Uso de anticoncepcionais orais ou terapia de reposição hormonal.\n- Doença inflamatória intestinal.\n- Doença cardíaca (ICC, IAM) ou respiratória crônica (DPOC ativa).\n- História prévia de TVP/EP.", category: "pneumologia", tags: ["tep", "tvp", "trombembolismo"] },
  { id: "fc-gen-pneumologia-005", front: "Qual é a dose recomendada de prednisona na tuberculose pulmonar para pacientes sem HIV que desenvolvem Síndrome Inflamatória de Reconstituição Imune (SIRI)?", back: "Para pacientes sem HIV que desenvolvem SIRI relacionada à tuberculose pulmonar, a dose de prednisona recomendada é de 0,5 a 1 mg/kg/dia, geralmente por um período de 4 a 6 semanas, com desmame lento subsequente. O tratamento deve ser guiado pela resposta clínica e pela exclusão de outras causas de piora, como falha do tratamento antituberculose. É crucial que o tratamento antituberculose esteja em andamento e otimizado antes do início da corticoterapia para SIRI.", category: "pneumologia", tags: ["tuberculose", "siri", "corticosteroide"] },
  { id: "fc-gen-pneumologia-006", front: "Quais os critérios GOLD, revisados em 2024, para a classificação da DPOC quanto ao grau de limitação do fluxo aéreo?", back: "A classificação GOLD da DPOC utiliza o VEF1 pós-broncodilatador:\n• GOLD 1: Leve, VEF1 ≥ 80% do previsto\n• GOLD 2: Moderada, 50% ≤ VEF1 < 80% do previsto\n• GOLD 3: Grave, 30% ≤ VEF1 < 50% do previsto\n• GOLD 4: Muito grave, VEF1 < 30% do previsto", category: "pneumologia", tags: ["dpoc", "gold", "espirometria"] },
  { id: "fc-gen-pneumologia-007", front: "Qual a conduta inicial para uma crise asmática grave em adulto, segundo a GINA 2024, no pronto-socorro?", back: "A conduta inicial para crise asmática grave em adulto inclui:\n• Oxigenioterapia: alvo SpO2 93-95%\n• Beta-2 agonista de curta ação (SABA): 4-10 jatos por espaçador a cada 20 min por 1h, ou nebulização contínua ou intermitente\n• Corticosteroide sistêmico: Prednisolona 40-50 mg VO ou Metilprednisolona 40-80 mg IV\n• Ipratrópio: combinado ao SABA na nebulização ou 4-8 jatos por espaçador", category: "pneumologia", tags: ["asma", "crise asmática", "gina"] },
  { id: "fc-gen-pneumologia-008", front: "Quais os critérios para indicação de oxigenoterapia domiciliar prolongada (ODP) na DPOC?", back: "A ODP é indicada para pacientes com DPOC que apresentem:\n• PaO2 ≤ 55 mmHg ou SaO2 ≤ 88% em repouso, respirando ar ambiente, com ou sem hipercapnia\n• PaO2 entre 56-59 mmHg ou SaO2 ≤ 89% em repouso, com evidência de cor pulmonale, hipertensão pulmonar ou policitemia (Ht > 55%)\n• O benefício é maior com > 15 horas/dia de uso.", category: "pneumologia", tags: ["dpoc", "odp", "hipoxemia"] },
  { id: "fc-gen-pneumologia-009", front: "Qual a dose e o tempo de uso do antibiótico na pneumonia adquirida na comunidade (PAC) não grave em pacientes sem comorbidades?", back: "Para PAC não grave em pacientes sem comorbidades, a dose e tempo de uso de antibiótico é:\n• Amoxicilina 500 mg a 1g 3x/dia por 5-7 dias.\n• Alternativas: Macrolídeos (Azitromicina 500 mg 1x/dia no dia 1, seguido de 250 mg 1x/dia por 4 dias) ou Doxiciclina 100 mg 2x/dia por 5-7 dias.", category: "pneumologia", tags: ["pac", "antibiótico", "pneumonia"] },
  { id: "fc-gen-pneumologia-010", front: "Quais os componentes do escore CURB-65 para avaliação de gravidade da pneumonia e qual sua utilidade?", back: "O escore CURB-65 avalia:\n• **C**onfusão mental (desorientação no tempo/espaço)\n• **U**reia > 7 mmol/L (ou > 20 mg/dL)\n• **R**eferência (Frequência respiratória) ≥ 30 irpm\n• **B**aixa pressão arterial (PAS < 90 mmHg ou PAD ≤ 60 mmHg)\n• Idade (≥) **65** anos\nTotaliza de 0 a 5 pontos, auxiliando na decisão de tratamento ambulatorial ou hospitalar.", category: "pneumologia", tags: ["curb-65", "pneumonia", "gravidade"] },
  { id: "fc-gen-pneumologia-011", front: "Qual a dose e o tempo de profilaxia de tromboembolismo venoso (TEV) com enoxaparina em pacientes clínicos hospitalizados com risco moderado/alto?", back: "A dose de enoxaparina para profilaxia de TEV em pacientes clínicos hospitalizados é:\n• Enoxaparina 40 mg SC 1x/dia.\n• Em pacientes com insuficiência renal (CrCl < 30 mL/min), a dose deve ser reduzida para Enoxaparina 20 mg SC 1x/dia.\n• O tempo de uso geralmente é durante toda a internação, ou até a mobilização do paciente, podendo se estender por até 10-14 dias em algumas situações de alto risco.", category: "pneumologia", tags: ["tev", "profilaxia", "enoxaparina"] },
  { id: "fc-gen-pneumologia-012", front: "Quais os principais efeitos adversos dos Beta-2 agonistas de longa duração (LABA) utilizados na DPOC e asma?", back: "Os principais efeitos adversos dos LABA incluem:\n• Tremor: mais comum, periférico e dose-dependente.\n• Palpitações e taquicardia: podem ocorrer devido à estimulação cardíaca.\n• Câimbras musculares: ocasionalmente.\n• Hipocalemia: por desvio de potássio para o intracelular.\n• Prolongamento do intervalo QT (raro).\n• Tosses e irritação na garganta (locais).", category: "pneumologia", tags: ["laba", "dpoc", "asma", "efeitos adversos"] },
  { id: "fc-gen-pneumologia-013", front: "Qual a diferença fisiopatológica fundamental entre asma e DPOC?", back: "A diferença fisiopatológica fundamental é:\n• Asma: Inflamação crônica das vias aéreas com hiperresponsividade brônquica reversível, caracterizada por obstrução variável do fluxo aéreo, mediada principalmente por eosinófilos e mastócitos.\n• DPOC: Doença inflamatória crônica progressiva, não totalmente reversível, com limitação persistente do fluxo aéreo, causada por resposta inflamatória anormal a partículas ou gases nocivos, mediada principalmente por neutrófilos, macrófagos e linfócitos T CD8+.", category: "pneumologia", tags: ["asma", "dpoc", "fisiopatologia"] },
  { id: "fc-gen-pneumologia-014", front: "Cite os quatro principais critérios de gravidade (critérios maiores) para internação em UTI na pneumonia grave.", back: "Os quatro critérios maiores para internação em UTI na pneumonia grave (ATS/IDSA) são:\n1. Necessidade de ventilação mecânica invasiva.\n2. Choque séptico com necessidade de vasopressores.\n3. Insuficiência respiratória que necessita de ventilação não invasiva (em algumas diretrizes, considerada critério menor).\n4. Rápida progressão ou envolvimento multilobar.", category: "pneumologia", tags: ["pneumonia grave", "uti", "critérios"] },
  { id: "fc-gen-pneumologia-015", front: "Qual a dose e o tempo de tratamento com oseltamivir no tratamento da gripe (influenza) em adultos?", back: "A dose recomendada de oseltamivir para tratamento da gripe em adultos é:\n• Oseltamivir 75 mg oral, 2x/dia, por 5 dias.\n• Deve ser iniciado preferencialmente dentro de 48 horas do início dos sintomas para otimizar a eficácia.", category: "pneumologia", tags: ["gripe", "influenza", "oseltamivir"] },
  { id: "fc-gen-pneumologia-016", front: "Qual o manejo inicial de um pneumotórax espontâneo primário pequeno (< 2 cm na radiografia) em paciente assintomático ou com sintomas leves?", back: "O manejo inicial para pneumotórax espontâneo primário pequeno (< 2 cm entre a pleura visceral e parietal na radiografia de tórax ápice-parede) em paciente assintomático ou com sintomas leves é:\n• Observação e acompanhamento clínico, com reavaliação radiológica em 24-48 horas.\n• Pode ser considerada aspiração simples se houver progressão ou sintomas.\n• Orientar o paciente sobre sinais de alerta para retorno imediato.\n• Evitar viagens aéreas e mergulho.", category: "pneumologia", tags: ["pneumotórax", "manejo", "radiologia"] },
  { id: "fc-gen-pneumologia-017", front: "Quais as indicações para intubação orotraqueal em uma crise asmática grave que não responde ao tratamento inicial?", back: "Indicações para intubação orotraqueal em crise asmática grave refratária incluem:\n• Exaustão respiratória iminente (fadiga muscular, queda do nível de consciência).\n• Hipóxia refratária (PaO2 < 60 mmHg com FiO2 > 50-60%) ou PaCO2 em ascensão.\n• Acidose respiratória grave (pH < 7.25).\n• PCR ou parada respiratória iminente.\n• Arritmias graves ou instabilidade hemodinâmica.", category: "pneumologia", tags: ["asma grave", "intubação", "insuficiência respiratória"] },
  { id: "fc-gen-pneumologia-018", front: "Qual a dose de manutenção de tiotrópio na DPOC?", back: "A dose de manutenção de tiotrópio (um anticolinérgico de longa duração - LAMA) na DPOC é:\n• 18 mcg, inalado 1x/dia, via inalador de pó seco (Handihaler).\n• Ou 2.5 mcg (2 puffs de 2.5 mcg = 5 mcg) do Respimat, 1x/dia.", category: "pneumologia", tags: ["dpoc", "tiotrópio", "lama"] },
  { id: "fc-gen-pneumologia-019", front: "Quais os principais agentes patogênicos envolvidos na PAC em pacientes ambulatoriais sem comorbidades?", back: "Os principais agentes patogênicos na PAC em pacientes ambulatoriais sem comorbidades são:\n• *Streptococcus pneumoniae* (o mais comum).\n• *Mycoplasma pneumoniae*.\n• *Chlamydophila pneumoniae*.\n• Vírus respiratórios (Influenza, Rinovírus, Coronavírus, Adenovírus).\n• *Haemophilus influenzae*.", category: "pneumologia", tags: ["pac", "etiologia", "pneumonia"] },
  { id: "fc-gen-pneumologia-020", front: "Qual a principal diferença entre os testes tuberculínicos (PPD) e os exames de IGRA (Interferon-Gamma Release Assays) para diagnóstico de infecção latente por *Mycobacterium tuberculosis* (ILTB)?", back: "A principal diferença reside em:\n• PPD (Teste Tuberculínico): mede a resposta imune celular mediada por linfócitos T a antígenos PPD, que são compartilhados por *M. tuberculosis* e outras micobactérias não tuberculosas, e pela vacina BCG. Pode ter falsos positivos.\n• IGRA: mede a produção de interferon-gama por linfócitos T em resposta a antígenos específicos do *M. tuberculosis* (ESAT-6 e CFP-10) que não estão presentes nas cepas vacinais de BCG ou na maioria das micobactérias não tuberculosas. É mais específico.", category: "pneumologia", tags: ["iltb", "ppd", "igra", "tuberculose"] },
  { id: "fc-gen-pneumologia-021", front: "Qual antibiótico é a primeira escolha para o tratamento da tuberculose latente (ILTB), de acordo com as diretrizes do Ministério da Saúde do Brasil?", back: "A primeira escolha para o tratamento da ILTB, conforme o MS-Brasil, é:\n• Isoniazida 300 mg/dia por 6 a 9 meses.\n• Regimes alternativos mais curtos, como Isoniazida + Rifapentina semanal por 3 meses, ou Rifampicina 10 mg/kg/dia por 4 meses, são opções dependendo da avaliação clínica e disponibilidade.", category: "pneumologia", tags: ["iltb", "tuberculose", "isoniazida", "ms-brasil"] },
  { id: "fc-gen-pneumologia-022", front: "Quais os achados espirométricos característicos da DPOC, segundo a GOLD?", back: "Os achados espirométricos característicos da DPOC para confirmação diagnóstica são:\n• VEF1/CVF (Índice de Tiffeneau) < 0.70 pós-broncodilatador.\n• Este achado denota limitação persistente do fluxo aéreo.\n• A gravidade da obstrução é então classificada pelo VEF1 pós-broncodilatador em GOLD 1-4.", category: "pneumologia", tags: ["dpoc", "espirometria", "gold"] },
  { id: "fc-gen-pneumologia-023", front: "Quais os critérios diagnósticos para asma, de acordo com GINA 2024?", back: "O diagnóstico de asma (GINA 2024) é baseado em:\n• Histórico de sintomas respiratórios variáveis (sibilância, dispneia, tosse, aperto no peito).\n• Evidência de limitação variável e reversível do fluxo aéreo na espirometria (aumento do VEF1 pós-broncodilatador ≥ 12% E ≥ 200 ml, ou hiperresponsividade brônquica).", category: "pneumologia", tags: ["asma", "diagnóstico", "gina"] },
  { id: "fc-gen-pneumologia-024", front: "Em um paciente com suspeita de embolia pulmonar (EP), qual o papel do D-dímero?", back: "O D-dímero é útil para exclusão de EP em pacientes de baixa ou intermediária probabilidade pré-teste (escore de Wells ou Genebra revisado):\n• D-dímero normal (geralmente < 500 ng/mL) **exclui** EP com alta sensibilidade em pacientes de baixa probabilidade.\n• D-dímero elevado **não confirma** EP, sendo inespecífico, e requer investigação adicional (ex: angio-TC de tórax).\n• É menos útil para excluir EP em alta probabilidade pré-teste ou em pacientes hospitalizados (muitos fatores podem elevá-lo).", category: "pneumologia", tags: ["embolia pulmonar", "d-dímero", "diagnóstico"] },
  { id: "fc-gen-pneumologia-025", front: "Qual o tratamento de escolha para uma embolia pulmonar de alto risco (instabilidade hemodinâmica)?", back: "O tratamento de escolha para embolia pulmonar de alto risco (instabilidade hemodinâmica, choque ou hipotensão persistente) é:\n• Terapia trombolítica sistêmica com alteplase (ex: 100 mg IV em 2h).\n• Em casos específicos, como contraindicação à trombólise ou falha, pode-se considerar a trombectomia cirúrgica ou por cateter.", category: "pneumologia", tags: ["embolia pulmonar", "trombólise", "ep"] },
  { id: "fc-gen-pneumologia-026", front: "Quais as indicações para o uso de ventilação não invasiva (VNI) na exacerbação aguda da DPOC (EADPOC)?", back: "As indicações para VNI na EADPOC incluem:\n• Acidose respiratória (pH < 7.35 e PaCO2 > 45 mmHg).\n• Dispneia moderada a grave com uso de musculatura acessória e/ou movimento abdominal paradoxal.\n• Frequência respiratória > 25 irpm.\n• Diminuição da PaO2 e/ou aumento da PaCO2 após tratamento inicial.", category: "pneumologia", tags: ["dpoc", "vni", "exacerbação"] },
  { id: "fc-gen-pneumologia-027", front: "Qual a dose e o esquema de tratamento para tuberculose pulmonar sensível a drogas, segundo o MS-Brasil?", back: "O esquema do MS-Brasil para tuberculose pulmonar sensível é:\n• Fase Intensiva (2 meses): 4 drogas (Rifampicina + Isoniazida + Pirazinamida + Etambutol)\n  • Rifampicina: 10 mg/kg/dia (dose máx. 600 mg)\n  • Isoniazida: 5 mg/kg/dia (dose máx. 300 mg)\n  • Pirazinamida: 25 mg/kg/dia (dose máx. 1500 mg)\n  • Etambutol: 15 mg/kg/dia (dose máx. 1000 mg)\n• Fase de Manutenção (4 meses): 2 drogas (Rifampicina + Isoniazida)", category: "pneumologia", tags: ["tuberculose", "tratamento", "ms-brasil"] },
  { id: "fc-gen-pneumologia-028", front: "Quais os principais efeitos adversos da Rifampicina, utilizada no tratamento da tuberculose?", back: "Os principais efeitos adversos da Rifampicina incluem:\n• Hepatotoxicidade (elevação de transaminases, hepatite).\n• Coloração alaranjada da urina, saliva, lágrimas (importante orientar o paciente).\n• Gastrintestinais (náuseas, vômitos, dor abdominal).\n• Reações cutâneas (rash).\n• Interações medicamentosas significativas (potente indutor de CYP450).\n• Trombocitopenia (rara).", category: "pneumologia", tags: ["tuberculose", "rifampicina", "efeitos adversos"] },
  { id: "fc-gen-pneumologia-029", front: "Qual a definição de tosse crônica e suas causas mais comuns em adultos?", back: "Tosse crônica é definida como tosse que persiste por 8 semanas ou mais. As causas mais comuns em adultos são:\n• Síndrome da tosse das vias aéreas superiores (anteriormente gotejamento pós-nasal).\n• Asma (inclusive variante tosse).\n• Doença do refluxo gastroesofágico (DRGE).\n• DPOC (em tabagistas ou ex-tabagistas).\n• Bronquiectasias.\n• Uso de IECA.", category: "pneumologia", tags: ["tosse crônica", "diagnóstico", "pneumologia"] },
  { id: "fc-gen-pneumologia-030", front: "Quais os cuidados essenciais na abordagem de um paciente com derrame pleural de causa desconhecida?", back: "Os cuidados essenciais incluem:\n• Estabilização clínica do paciente (se necessário).\n• Realização de radiografia de tórax e/ou ultrassonografia pleural para confirmar o derrame.\n• Toracocentese diagnóstica (se houver líquido suficiente e não houver contraindicações) para análise físico-química, citológica e microbiológica.\n• Interpretação dos critérios de Light para classificar em transudato ou exsudato (ex: proteínas líquido/soro > 0.5, DHL líquido/soro > 0.6, DHL líquido > 2/3 do limite superior do DHL sérico).\n• Investigação complementar conforme resultado da análise do líquido (biópsia pleural, broncoscopia, exames de imagem adicionais).", category: "pneumologia", tags: ["derrame pleural", "toracocentese", "critérios de light"] },
  { id: "fc-gen-cardiologia-006", front: "Quais são os critérios diagnósticos para Síndrome de Takotsubo (Cardiomiopatia por Estresse)?", back: "1. Disfunção transitória do VE (acinesia, hipocinesia ou discinesia) em segmentos do pico do coração, com ou sem envolvimento mesoventricular, estendendo-se além de um único território coronariano.\n2. Geralmente, uma causa aguda de estresse emocional ou físico precipitante.\n3. Ausência de doença arterial coronariana obstrutiva ou evidências de ruptura aguda de placa.\n4. Novas alterações eletrocardiográficas (elevação de ST, inversão de T, prolongamento de QT) e/ou elevação de troponina.\n5. Ausência de miocardite, feocromocitoma ou cardiomiopatia hipertrófica.", category: "cardiologia", tags: ["cardiomiopatia", "takotsubo"] },
  { id: "fc-gen-cardiologia-007", front: "Qual a dose e via de administração da nitroglicerina sublingual para alívio de angina?", back: "Dose: 0,4 mg (um comprimido ou borrifada)\nVia: Sublingual (SL)\nAdministração: Pode ser repetida a cada 5 minutos por até 3 doses em um período de 15 minutos. Se a dor persistir após a terceira dose ou piorar, procurar atendimento médico de emergência.", category: "cardiologia", tags: ["angina", "nitroglicerina"] },
  { id: "fc-gen-cardiologia-008", front: "Quais são as classes de fármacos recomendadas para o tratamento da insuficiência cardíaca com fração de ejeção reduzida (ICFEd)?", back: "As classes fundamentais para ICFEr incluem:\n- Inibidores da ECA (IECA) ou Bloqueadores dos Receptores da Angiotensina (BRA) ou Inibidores da Neprilisina e do Receptor da Angiotensina (INRA).\n- Betabloqueadores (BB).\n- Antagonistas do Receptor de Mineralocorticoides (ARM).\n- Inibidores do Cotransportador de Sódio-Glicose 2 (iSGLT2).", category: "cardiologia", tags: ["insuficiência cardíaca", "icfed"] },
  { id: "fc-gen-cardiologia-009", front: "Quais são os principais fatores de risco modificáveis para doença arterial coronariana?", back: "Os principais fatores de risco modificáveis são:\n- Hipertensão Arterial Sistêmica (HAS)\n- Dislipidemia (principalmente LDL alto)\n- Diabetes Mellitus (DM)\n- Tabagismo\n- Obesidade/Sobrepeso\n- Sedentarismo\n- Estresse psicossocial", category: "cardiologia", tags: ["fator de risco", "dac"] },
  { id: "fc-gen-cardiologia-010", front: "Qual a conduta inicial para um paciente com taquicardia ventricular monomórfica sustentada com instabilidade hemodinâmica?", back: "A conduta inicial é a cardioversão elétrica sincronizada imediata.\nDose inicial recomendada: 100 J a 200 J (monofásica) ou 50 J a 100 J (bifásica). Em caso de falha, aumentar a energia. Sedar o paciente, se houver tempo.", category: "cardiologia", tags: ["arritmia", "tvm"] },
  { id: "fc-gen-cardiologia-011", front: "Quais os critérios maiores e menores de Duke para diagnóstico de endocardite infecciosa?", back: "Critérios Maiores:\n- Hemoculturas positivas para um microrganismo típico.\n- Evidência de envolvimento endocárdico (ecocardiograma: vegetação, abscesso, nova deiscência de prótese, nova regurgitação valvular).\n\nCritérios Menores:\n- Predisposição cardíaca ou uso de drogas intravenosas.\n- Febre (≥ 38,0°C).\n- Fenômenos vasculares (êmbolos arteriais maiores, infarto pulmonar séptico, aneurisma micótico, hemorragia intracraniana, hemorragias conjuntivais, lesões de Janeway).\n- Fenômenos imunológicos (glomerulonefrite, nódulos de Osler, manchas de Roth, fator reumatoide).\n- Evidência microbiológica (hemocultura não preenche critério maior ou evidência sorológica de infecção ativa com organismo de EI).", category: "cardiologia", tags: ["endocardite", "duke"] },
  { id: "fc-gen-cardiologia-012", front: "Qual o principal mecanismo de ação dos iSGLT2 no tratamento da insuficiência cardíaca?", back: "Os iSGLT2 atuam principalmente pela inibição do cotransportador SGLT2 nos túbulos renais, levando a:\n- Glicosúria e natriurese, reduzindo a pré-carga e a pós-carga.\n- Efeitos renais protetores (diminuição da hiperfiltração e fibrose).\n- Melhora do metabolismo cardíaco (mudança para corpos cetônicos como fonte de energia).\n- Efeitos anti-inflamatórios e antifibróticos.", category: "cardiologia", tags: ["insuficiência cardíaca", "isglt2"] },
  { id: "fc-gen-cardiologia-013", front: "Como é calculado o escore CHADS-VASc para estratificação de risco de AVC em Fibrilação Atrial?", back: "O escore CHADS-VASc atribui pontos para os seguintes fatores:\n- C: Insuficiência Cardíaca (1 ponto)\n- H: Hipertensão (1 ponto)\n- A: Idade ≥ 75 anos (2 pontos)\n- D: Diabetes Mellitus (1 ponto)\n- S2: AVC/AIT/Tromboembolismo prévio (2 pontos)\n- V: Doença Vascular (IAM prévio, doença arterial periférica, placa aterosclerótica aórtica) (1 ponto)\n- A: Idade 65-74 anos (1 ponto)\n- S: Sexo Feminino (1 ponto)", category: "cardiologia", tags: ["fa", "chads-vasc"] },
  { id: "fc-gen-cardiologia-014", front: "Quando é indicada a terapia com estatinas de alta intensidade para prevenção secundária de doença cardiovascular aterosclerótica (DCVA)?", back: "É indicada para pacientes com DCVA estabelecida (IAM prévio, AVC isquêmico, doença arterial periférica) com o objetivo de reduzir o LDL-C em ≥ 50% ou para um alvo de LDL-C < 70 mg/dL (ou < 55 mg/dL em muito alto risco).\nExemplos de estatinas de alta intensidade: Atorvastatina 40-80 mg, Rosuvastatina 20-40 mg.", category: "cardiologia", tags: ["dislipidemia", "estatinas"] },
  { id: "fc-gen-cardiologia-015", front: "Quais são as alterações eletrocardiográficas sugestivas de isquemia miocárdica no SCA S/ST supra (IAMCSST)?", back: "As alterações sugestivas são:\n- Elevação do segmento ST em duas ou mais derivações contíguas:\n  - ≥ 1 mm em todas as derivações, exceto V2-V3.\n  - Em V2-V3, ≥ 2 mm para homens ≥ 40 anos, ≥ 2,5 mm para homens < 40 anos, ≥ 1,5 mm para mulheres.\n- Novo bloqueio de ramo esquerdo (BRE) presumivelmente novo.\n- Elevação de ST em aVR (em alguns contextos).\n- Onda T hiperaguda.", category: "cardiologia", tags: ["ecg", "iamcsst"] },
  { id: "fc-gen-cardiologia-016", front: "Qual a dose de ataque recomendada de aspirina e clopidogrel para um paciente com Síndrome Coronariana Aguda (SCA)?", back: "Doses de ataque comuns:\n- Aspirina: 150 mg a 300 mg (mastigar ou VO), o mais rápido possível.\n- Clopidogrel:\n  - Se intervenção coronariana percutânea (ICP) programada: 300 mg a 600 mg VO.\n  - Se tratamento conservador: 75 mg a 300 mg VO. (AHA recomenda 300mg para pacientes < 75a ao não indicar PCI de imediato)", category: "cardiologia", tags: ["sca", "antiagregante"] },
  { id: "fc-gen-cardiologia-017", front: "Qual a principal indicação e dose do sacubitril/valsartana na ICFEd?", back: "Indicado como substituto dos IECA/BRA em pacientes sintomáticos com ICFEd (FEVE ≤ 40% pela ESC, ≤ 35% pela AHA) que permanecem sintomáticos apesar da terapia otimizada com IECA/BRA, betabloqueador e ARM.\nDose inicial: Geralmente 49/51 mg a cada 12h, podendo ser otimizado até 97/103 mg a cada 12h. É crucial um período de washout de 36 horas entre a suspensão do IECA e o início do sacubitril/valsartana devido ao risco de angioedema.", category: "cardiologia", tags: ["icfed", "inra"] },
  { id: "fc-gen-cardiologia-018", front: "Quais são os principais agentes fibrinolíticos utilizados no tratamento do IAMCSST?", back: "Os principais agentes fibrinolíticos (também chamados de trombolíticos) são:\n- Alteplase (r-tPA)\n- Tenecteplase (TNK-tPA)\n- Estreptoquinase\nTenecteplase é preferível por ser administrada em bolus único e ter alta especificidade por fibrina.", category: "cardiologia", tags: ["iamcsst", "trombólise"] },
  { id: "fc-gen-cardiologia-019", front: "Como deve ser o manejo da hipertensão arterial em uma crise hipertensiva com emergência, por exemplo, com edema agudo de pulmão?", back: "Em emergências hipertensivas, como o edema agudo de pulmão, o objetivo é reduzir a pressão arterial rapidamente (geralmente 20-25% na primeira hora) para evitar dano a órgãos-alvo.\n- Terapia: Nitroglicerina IV ou nitroprussiato de sódio IV são as opções de primeira linha, pela sua ação vasodilatadora rápida e potente. Furosemida IV para o edema pulmonar. Adicionalmente, CPAP/BiPAP e oxigênio.", category: "cardiologia", tags: ["hipertensão", "emergência"] },
  { id: "fc-gen-cardiologia-020", front: "Quais as indicações para o uso de betabloqueadores em pacientes pós-infarto agudo do miocárdio?", back: "Os betabloqueadores são indicados rotineiramente para todos os pacientes pós-IAM, a menos que haja contraindicações.\nIndicações:\n- Prevenção de arritmias ventriculares.\n- Redução da carga de trabalho cardíaca e consumo de oxigênio.\n- Melhora da sobrevida e redução de eventos cardiovasculares adversos maiores.\n- Principalmente em pacientes com disfunção do VE.", category: "cardiologia", tags: ["iam", "betabloqueador"] },
  { id: "fc-gen-cardiologia-021", front: "Qual a indicação de anticoagulação oral para pacientes com fibrilação atrial não valvular com escore CHADS-VASc de 1 (homem) ou 2 (mulher)?", back: "A decisão é individualizada, mas as diretrizes recentes sugerem:\n- Homens com CHADS-VASc de 1: Considerar anticoagulação oral (preferencialmente NOAC).\n- Mulheres com CHADS-VASc de 2: Considerar anticoagulação oral (preferencialmente NOAC).\nEm ambos os cenários, o risco de sangramento deve ser cuidadosamente avaliado (HAS-BLED).", category: "cardiologia", tags: ["fa", "anticoagulação"] },
  { id: "fc-gen-cardiologia-022", front: "Quais os tipos de revascularização miocárdica em pacientes com doença arterial coronariana?", back: "Os dois principais tipos de revascularização miocárdica são:\n1. Angioplastia Coronariana Percutânea (ICP com stent): É um procedimento minimamente invasivo, onde um cateter com balão é usado para abrir a artéria estreitada e um stent é frequentemente implantado para mantê-la aberta.\n2. Revascularização Miocárdica Cirúrgica (RM, ou Ponte de Safena/Mamária): Cirurgia de \"बाईपास\" cardíaco, onde são criadas novas vias para o sangue fluir ao redor das artérias coronárias bloqueadas, usando veias ou artérias de outras partes do corpo.", category: "cardiologia", tags: ["dac", "revascularização"] },
  { id: "fc-gen-cardiologia-023", front: "Quais são as principais contraindicações absolutas para o uso de fibrinolíticos no IAMCSST?", back: "Contraindicações absolutas incluem:\n- AVC hemorrágico ou AVC de causa desconhecida prévios.\n- AVC isquêmico nos últimos 6 meses.\n- Neoplasia intracraniana primária ou malformação arteriovenosa.\n- Trauma crânio-encefálico ou facial significativo ou cirurgia de grande porte nos últimos 3 meses.\n- Sangramento gastrointestinal ativo nos últimos 1 mês.\n- Suspeita de dissecção de aorta.\n- Punções não compressíveis nas últimas 24h.", category: "cardiologia", tags: ["iamcsst", "fibrinolítico"] },
  { id: "fc-gen-cardiologia-024", front: "Qual o manejo inicial da taquicardia supraventricular (TSV) com estabilidade hemodinâmica?", back: "1. Manobras vagais (Valsalva modificada, massagem do seio carotídeo).\n2. Adenosina IV (6 mg rápido, seguido de bolus de soro fisiológico; se não converter, 12 mg, podendo repetir).\n3. Betabloqueadores IV (ex: metoprolol) ou bloqueadores de canal de cálcio (ex: verapamil, diltiazem) se a adenosina for contraindicada ou não surtir efeito.\n4. Cardioversão elétrica sincronizada em casos refratários ou instabilidade hemodinâmica emergente.", category: "cardiologia", tags: ["taquicardia", "adenosina"] },
  { id: "fc-gen-cardiologia-025", front: "Qual a dose e o período de uso da dupla antiagregação plaquetária (DAPT) após ICP com stent farmacológico em SCA?", back: "A DAPT consiste em Aspirina + um inibidor P2Y12 (Clopidogrel, Ticagrelor ou Prasugrel).\n- Aspirina: 75-100 mg/dia (manutenção).\n- Inibidor P2Y12:\n  - Ticagrelor 90 mg 2x/dia ou Prasugrel 10 mg 1x/dia são preferidos.\n  - Clopidogrel 75 mg 1x/dia, se os anteriores forem contraindicados.\nPeríodo: Mínimo de 12 meses após SCA com stent farmacológico. Pode ser estendido ou encurtado dependendo do risco isquêmico vs. risco hemorrágico.", category: "cardiologia", tags: ["sca", "dapt"] },
  { id: "fc-gen-cardiologia-026", front: "Quais são os estágios da insuficiência cardíaca de acordo com a AHA/ACC?", back: "Os estágios da IC segundo a AHA/ACC são:\n- Estágio A: Alto risco de IC, mas sem doença cardíaca estrutural ou sintomas.\n- Estágio B: Doença cardíaca estrutural presente, mas sem sinais ou sintomas de IC.\n- Estágio C: Doença cardíaca estrutural e sintomas prévios ou atuais de IC.\n- Estágio D: IC refratária que requer intervenções especializadas.", category: "cardiologia", tags: ["insuficiência cardíaca", "estagiamento"] },
  { id: "fc-gen-cardiologia-027", front: "Qual o principal efeito colateral da amiodarona em uso crônico e como monitorar?", back: "A amiodarona, quando usada cronicamente, possui múltiplos efeitos colaterais devido ao seu teor de iodo e perfil lipofílico.\n- Principal: Toxicidade tireoidiana (hipo ou hipertireoidismo), toxicidade pulmonar (fibrose), toxicidade hepática, toxicidade ocular (depósitos na córnea) e neuropatia periférica.\n- Monitoramento: Testes de função tireoidiana (TSH, T4L), transaminases hepáticas, função pulmonar e avaliação oftalmológica devem ser realizados periodicamente (ex: a cada 6 meses).", category: "cardiologia", tags: ["amiodarona", "arritmia"] },
  { id: "fc-gen-cardiologia-028", front: "Quais as principais intervenções de estilo de vida para o controle da hipertensão arterial?", back: "As principais intervenções de estilo de vida incluem:\n- Restrição do consumo de sódio (< 2g/dia ou < 5g de cloreto de sódio).\n- Dieta DASH (rica em frutas, vegetais, grãos integrais, laticínios desnatados e pobre em gorduras saturadas).\n- Limitação do consumo de álcool (≤ 2 doses/dia para homens, ≤ 1 dose/dia para mulheres).\n- Atividade física regular (≥ 150 min/semana de exercício aeróbico moderado).\n- Controle de peso (manter IMC 18,5–24,9 kg/m²).\n- Cessação do tabagismo.", category: "cardiologia", tags: ["hipertensão", "estilo de vida"] },
  { id: "fc-gen-cardiologia-029", front: "Qual a classificação da valvopatia aórtica de acordo com o gradiente de pressão e área valvar?", back: "Para estenose aórtica, a classificação é baseada no gradiente médio e na área da valva:\n- Leve: Gradiente médio < 20 mmHg; Área valvar > 1,5 cm².\n- Moderada: Gradiente médio 20-39 mmHg; Área valvar 1,0-1,5 cm².\n- Grave: Gradiente médio ≥ 40 mmHg; Área valvar < 1,0 cm².", category: "cardiologia", tags: ["valvopatia", "estenose aórtica"] },
  { id: "fc-gen-cardiologia-030", front: "Quais as doses de heparina não fracionada (HNF) para anticoagulação em SCA sem elevação de ST (SCASSST) ou IAMCSST com contraindicação a fibrinolíticos/ICP imediata?", back: "As doses de HNF são geralmente ajustadas pelo peso:\n- Bolus IV: 60 U/kg (máximo 4000 U).\n- Infusão contínua IV: Início com 12 U/kg/h (máximo 1000 U/h).\n- Ajuste: Monitorizar pelo tempo de tromboplastina parcial ativada (TTPA) para manter 1,5 a 2,5 vezes o valor basal ou controle (geralmente um alvo entre 50-70 segundos).", category: "cardiologia", tags: ["scasst", "anticoagulação"] },
  { id: "fc-gen-cardiologia-031", front: "Quais os escores TIMI (Thrombolysis in Myocardial Infarction) de risco para SCA sem supradesnivelamento do segmento ST (IAMSST/UA)?", back: "O escore TIMI estratifica risco de eventos em 14 dias.\nCada item vale 1 ponto:\n- Idade ≥ 65 anos\n- ≥ 3 fatores de risco (HAS, DM, DLP, tabagismo, histórico familiar de DAC precoce)\n- Uso de AAS nos últimos 7 dias\n- Estenose coronariana pré-existente conhecida ≥ 50%\n- Desvio do segmento ST (infra ou supra transitório)\n- Elevação de marcadores de necrose miocárdica\n- ≥ 2 episódios de angina nas últimas 24h", category: "cardiologia", tags: ["timi", "iam", "scaspsst"] },
  { id: "fc-gen-cardiologia-032", front: "Qual o critério diagnóstico para hipertensão arterial utilizando a medida da pressão arterial no consultório, conforme as diretrizes brasileiras?", back: "Diagnóstico de HAS no consultório:\n- PA ≥ 140/90 mmHg em pelo menos 2 visitas distintas.\n- Critérios complementares:\n  - MAPA ou MRPA confirmando HAS, ou\n  - Presença de lesão em órgão-alvo.\n- Pode ser diagnosticada em uma única consulta se PA ≥ 180/110 mmHg com lesão de órgão-alvo ou risco cardiovascular muito alto.", category: "cardiologia", tags: ["has", "diagnóstico", "diretrizes"] },
  { id: "fc-gen-cardiologia-033", front: "Quais os medicamentos de primeira linha para tratamento da insuficiência cardíaca com fração de ejeção reduzida (ICFEd) sintomática, sem contraindicações?", back: "As quatro classes fundamentais de tratamento (GDMT) são:\n- Inibidores da SGLT2 (iSGLT2): empagliflozina, dapagliflozina\n- Inibidores da neprilisina e do receptor da angiotensina (INRA): sacubitril/valsartana (ou IECA/BRA se intorelância)\n- Betabloqueadores (BB): carvedilol, metoprolol succinato, bisoprolol\n- Antagonistas do receptor mineralocorticoide (ARM): espironolactona, eplerenona", category: "cardiologia", tags: ["icfed", "tratamento", "gdmt"] },
  { id: "fc-gen-cardiologia-034", front: "Quais os critérios para indicação de trombólise no infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST) na ausência de angioplastia primária?", back: "Indicações de trombólise:\n- Dor torácica isquêmica (>20 min, <12h) e\n- IAMCSST com supradesnivelamento ST ≥ 1mm em ≥ 2 derivações contíguas ou novo BRE.\nContraindicações absolutas:\n- AVC isquêmico < 3 meses\n- AVC hemorrágico prévio ou malformação AV cerebral conhecida\n- Neoplasia intracraniana primária ou metastática\n- Trauma crânio-encefálico ou facial significativo < 3 meses\n- Cirurgia intraespinhal ou intracraniana < 3 meses\n- Sangramento ativo ou diátese hemorrágica conhecida (exceto menstruação)\n- Dissecção de aorta", category: "cardiologia", tags: ["iamcsst", "trombólise", "reperfusão"] },
  { id: "fc-gen-cardiologia-035", front: "Quais os parâmetros para o diagnóstico de choque cardiogênico?", back: "O choque cardiogênico é uma condição de grave hipoperfusão tecidual devido à disfunção cardíaca. Apresenta:\n- Hipotensão persistente: PAS < 90 mmHg por > 30 min SEM reversão com volume OU PAM < 65 mmHg.\n- Índice cardíaco < 2,2 L/min/m² com pressão capilar pulmonar > 18 mmHg (critérios hemodinâmicos).\n- Sinais de hipoperfusão: oligúria (<0,5 mL/kg/h), alteração de nível de consciência, extremidades frias, acidose metabólica (lactato elevado).", category: "cardiologia", tags: ["choquecardiogênico", "diagnóstico", "hemodinâmica"] },
  { id: "fc-gen-cardiologia-036", front: "Qual a dose de ataque e de manutenção do AAS na síndrome coronariana aguda (SCA)?", back: "Na SCA:\n- Dose de ataque: 150-300 mg (preferencialmente mastigado).\n- Dose de manutenção: 75-100 mg/dia indefinidamente.", category: "cardiologia", tags: ["aas", "sca", "antiagregante"] },
  { id: "fc-gen-cardiologia-037", front: "Quais os principais efeitos adversos da amiodarona em uso prolongado?", back: "A amiodarona possui uma ampla gama de efeitos adversos devido à sua lipossolubilidade e longa meia-vida:\n- Tireoidopatia (hipo ou hipertireoidismo).\n- Toxicidade pulmonar (pneumonite, fibrose pulmonar).\n- Toxicidade hepática (elevação de transaminases, hepatite).\n- Neuropatia periférica.\n- Alterações cutâneas (fotosensibilidade, coloração azul-acinzentada).\n- Bradicardia, bloqueios atrioventriculares.\n- Depósitos corneanos (microdepósitos visíveis ao exame oftalmológico).", category: "cardiologia", tags: ["amiodarona", "efeitos adversos", "antiarrítmico"] },
  { id: "fc-gen-cardiologia-038", front: "Qual a definição de crise hipertensiva e quais suas duas principais categorias?", back: "Crise hipertensiva é definida por elevação abrupta e acentuada da pressão arterial (geralmente PAS ≥ 180 mmHg e/ou PAD ≥ 120 mmHg).\nSuas duas categorias são:\n- Urgência hipertensiva: PA muito elevada SEM lesão aguda e progressiva de órgão-alvo. O tratamento pode ser oral, em horas.\n- Emergência hipertensiva: PA muito elevada COM lesão aguda e progressiva de órgão-alvo (ex: encefalopatia, edema pulmonar agudo, dissecção aórtica, IAM, AVC). Exige redução imediata da PA com medicação endovenosa e monitorização.", category: "cardiologia", tags: ["crisehipertensiva", "urgência", "emergência"] },
  { id: "fc-gen-cardiologia-039", front: "Quais os fatores de risco convencionais para doença arterial coronariana (DAC)?", back: "Os principais fatores de risco para DAC incluem:\n- Dislipidemia (colesterol total elevado, LDL-c elevado, HDL-c baixo)\n- Hipertensão arterial sistêmica (HAS)\n- Diabetes mellitus (DM)\n- Tabagismo\n- Obesidade (principalmente abdominal)\n- Sedentarismo\n- História familiar de doença cardiovascular precoce (pais ou irmãos com DAC antes dos 55 anos para homens ou 65 anos para mulheres)\n- Idade avançada (homens ≥ 45 anos, mulheres ≥ 55 anos)", category: "cardiologia", tags: ["dac", "risco", "prevenção"] },
  { id: "fc-gen-cardiologia-040", front: "Qual o tratamento farmacológico inicial recomendado para fibrilação atrial (FA) de novo ou paroxística com resposta ventricular rápida em paciente estável?", back: "O tratamento inicial foca no controle da frequência cardíaca:\n- Betabloqueadores (BB): metoprolol, esmolol (IV em agudo), propranolol.\n- Bloqueadores dos canais de cálcio não diidropiridínicos (BCC não-DID): diltiazem, verapamil (IV em agudo).\n- Em casos de ICFEr, betabloqueadores são preferidos, se tolerados.\n- Considerar anticoagulação se CHA2DS2-VASc escore ≥ 2 em homens ou ≥ 3 em mulheres.", category: "cardiologia", tags: ["fa", "controlefrequência", "antiarritmico"] },
  { id: "fc-gen-cardiologia-041", front: "Quais são os componentes do escore CHA2DS2-VASc e qual sua utilidade clínica?", back: "CHA2DS2-VASc é um escore para avaliar o risco de acidente vascular cerebral em pacientes com fibrilação atrial não valvar.\nCada item vale 1 ponto, exceto AVC/AIT/TE prévio e idade ≥ 75 anos (2 pontos):\n- C: Insuficiência Cardíaca (1 ponto)\n- H: Hipertensão (1 ponto)\n- A2: Idade ≥ 75 anos (2 pontos)\n- D: Diabetes Mellitus (1 ponto)\n- S2: AVC/AIT/TE prévio (2 pontos)\n- V: Doença Vascular (IAM prévio, DAC, doença arterial periférica) (1 ponto)\n- A: Idade 65-74 anos (1 ponto)\n- Sc: Sexo feminino (1 ponto)", category: "cardiologia", tags: ["chads2vasc", "fa", "anticoagulação"] },
  { id: "fc-gen-cardiologia-042", front: "Qual a principal complicação do uso de heparina não fracionada (HNF) e como ela é monitorada?", back: "A principal complicação da HNF é o sangramento, incluindo a trombocitopenia induzida por heparina (TIH).\nA HNF é monitorada pelo tempo de tromboplastina parcial ativada (TTPA).\nO objetivo terapêutico do TTPA geralmente está entre 1,5 a 2,5 vezes o valor do controle (normalmente entre 60-80 segundos), dependendo do reagente do laboratório.", category: "cardiologia", tags: ["hnf", "anticoagulante", "sangramento"] },
  { id: "fc-gen-cardiologia-043", front: "Qual a abordagem para o tratamento da pericardite aguda idiopática?", back: "O tratamento da pericardite aguda idiopática visa aliviar os sintomas e prevenir recorrências:\n- Repouso.\n- Anti-inflamatórios não esteroides (AINEs) em altas doses por 1-2 semanas e desmame gradual (ex: ibuprofeno 600-800 mg 3x/dia ou colchicina 0,5-1 mg/dia).\n- Colchicina: tem papel importante na prevenção de recorrências, usada por 3-6 meses.\n- Corticosteroides: Reservados para casos refratários ou contraindicações/intolerância a AINEs/colchicina, usados com cautela devido ao risco de recorrência.", category: "cardiologia", tags: ["pericardite", "tratamento", "aaines"] },
  { id: "fc-gen-cardiologia-044", front: "Quais as indicações para o uso de tromboprofilaxia em pacientes internados não cirúrgicos, segundo a escala de risco de TEV de Padua (adaptada)?", back: "Indicações de tromboprofilaxia em pacientes internados não cirúrgicos, conforme o escore de Pádua (≥4 pontos):\n- Câncer ativo (3 pontos)\n- História de TEV (3 pontos)\n- Mobilidade reduzida (acamado ou restrição severa de mobilidade por ≥ 3 dias) (3 pontos)\n- Trombofilia conhecida (3 pontos)\n- Trauma/cirurgia nos últimos 30 dias (2 pontos)\n- Insuficiência cardíaca ou respiratória (1 ponto)\n- Infecção aguda/reumática (1 ponto)\n- IAM (1 ponto)\n- AVC isquêmico (1 ponto)\n- Obesidade (IMC ≥ 30 kg/m²) (1 ponto)\n- Idade ≥ 70 anos (1 ponto)", category: "cardiologia", tags: ["tev", "profilaxia", "padua"] },
  { id: "fc-gen-cardiologia-045", front: "Quais características definem uma estenose aórtica grave?", back: "A estenose aórtica é considerada grave quando os seguintes critérios ecocardiográficos são atendidos:\n- Área valvar aórtica (AVA) < 1,0 cm².\n- Velocidade máxima do jato > 4,0 m/s.\n- Gradiente de pressão médio > 40 mmHg.\n- A presença de sintomas (angina, síncope, dispneia) associada a esses parâmetros indica uma doença grave e geralmente sintomática.", category: "cardiologia", tags: ["ea", "estenoseaórtica", "critérios"] },
  { id: "fc-gen-cardiologia-046", front: "Qual a dose de clopidogrel na SCA (ataque e manutenção)?", back: "Na síndrome coronariana aguda (SCA) com clopidogrel:\n- Dose de ataque: 300 mg (em pacientes que não foram submetidos a ICP) ou 600 mg (antes ou durante ICP).\n- Dose de manutenção: 75 mg/dia por 12 meses (geralmente).", category: "cardiologia", tags: ["clopidogrel", "sca", "antiagregante"] },
  { id: "fc-gen-cardiologia-047", front: "Como diferenciar taquicardia supraventricular (TSV) com aberrância de taquicardia ventricular (TV) no ECG?", back: "A diferenciação é crucial e complexa, mas alguns critérios no ECG podem ajudar (critérios de Brugada):\n- Ausência de complexo RS no QRS precordial (todos os QRS positivos ou negativos sugerem TV).\n- Intervalo R-S > 100 ms em qualquer derivação precordial (sugere TV).\n- Dissociação AV (ondas P não relacionadas ao QRS ou bradicardia atrial em relação à TV) (patognomônico de TV).\n- Presença de QRS com morfologia de bloqueio de ramo não típica.\nNa dúvida, tratar como TV por ser a condição mais grave.", category: "cardiologia", tags: ["tsv", "tv", "ecg"] },
  { id: "fc-gen-cardiologia-048", front: "Quando a estatina de alta potência está indicada para prevenção primária em pacientes com dislipidemia, conforme as diretrizes brasileiras?", back: "Estatina de alta potência (ex: rosuvastatina 20-40mg ou atorvastatina 40-80mg) é indicada para prevenção primária nas seguintes situações:\n- Risco cardiovascular alto ou muito alto, mesmo com LDL-c limítrofe.\n- Diabéticos com ≥ 1 fator de risco cardiovascular ou com lesão em órgão-alvo.\n- Níveis de LDL-c > 190 mg/dL.\n- Doença renal crônica (clearance de creatinina < 60 mL/min).\nO objetivo é atingir metas de LDL-c (< 70 mg/dL para alto risco, < 50 mg/dL para muito alto risco).", category: "cardiologia", tags: ["estatina", "dislipidemia", "prevençãoprimária"] },
  { id: "fc-gen-cardiologia-049", front: "Qual o manejo inicial da dissecção aguda de aorta tipo A?", back: "A dissecção de aorta tipo A é uma emergência cirúrgica. O manejo inicial foca na estabilização do paciente e preparação para cirurgia:\n- Controle da pressão arterial: Manter PA sistólica entre 100-120 mmHg, utilizando betabloqueadores (ex: esmolol IV, labetalol IV) para reduzir a força de cisalhamento (dP/dt). Se a PA não for controlada, adicionar vasodilatadores (ex: nitroprussiato de sódio).\n- Controle da dor: Opioides (ex: morfina IV).\n- Preparação para cirurgia de emergência: Reparo cirúrgico é a conduta definitiva.\n- Monitorização intensiva.", category: "cardiologia", tags: ["dissecçãoaorta", "emergência", "tratamento"] },
  { id: "fc-gen-cardiologia-050", front: "Quais os critérios ecocardiográficos para a definição de hipertensão pulmonar?", back: "A hipertensão pulmonar é suspeitada no ecocardiograma quando:\n- Pressão sistólica da artéria pulmonar (PSAP) estimada > 35-40 mmHg em repouso\n- Estimada a partir do gradiente de regurgitação tricúspide (VRT) + pressão atrial direita (PAD).\nO diagnóstico definitivo e a classificação exigem cateterismo cardíaco direito, com pressão arterial pulmonar média (PAPm) ≥ 20 mmHg em repouso (definição mais recente da ESC/ERS 2022).", category: "cardiologia", tags: ["hipertensãopulmonar", "ecocardiograma", "diagnóstico"] },
  { id: "fc-gen-cardiologia-051", front: "Qual a dose de diltiazem IV para controle de frequência na fibrilação atrial com resposta ventricular rápida em paciente sem insuficiência cardíaca?", back: "Para controle da frequência na FA com resposta ventricular rápida, em pacientes hemodinamicamente estáveis e sem IC:\n- Dose de diltiazem IV: Ataque de 0,25 mg/kg IV em 2 minutos. Se não houver resposta adequada após 15 minutos, uma segunda dose de 0,35 mg/kg IV pode ser administrada.\n- Infusão de manutenção: 5 a 15 mg/hora, titulada para o controle da frequência desejada.", category: "cardiologia", tags: ["fa", "diltiazem", "controlefrequência"] },
  { id: "fc-gen-cardiologia-052", front: "Quais as indicações para o uso de desfibrilador cardioversor implantável (CDI) em prevenção primária de morte súbita cardíaca?", back: "O CDI é indicado para prevenção primária de morte súbita cardíaca em pacientes com:\n- Disfunção ventricular esquerda grave (FEVE ≤ 35%) de etiologia isquêmica ou não isquêmica, com sintomas de IC classe II ou III da NYHA, apesar de otimização terapêutica por pelo menos 3 meses.\n- Deve-se esperar pelo menos 40 dias após IAM e 90 dias após revascularização miocárdica (se aplicável), para reavaliar a FEVE.\n- Expectativa de vida funcional > 1 ano.", category: "cardiologia", tags: ["cdi", "prevenção", "morte-súbita"] },
  { id: "fc-gen-cardiologia-053", front: "Qual a conduta inicial para o edema agudo de pulmão cardiogênico?", back: "O manejo do edema agudo de pulmão cardiogênico (EAPC) é uma emergência e foca em reduzir a pré-carga, a pós-carga e melhorar a oxigenação:\n- Oxigenoterapia (VNI, se necessário).\n- Diuréticos de alça IV (furosemida 20-80 mg IV, repetindo conforme resposta).\n- Vasodilatadores (nitratos IV - nitroglicerina ou nitroprussiato) para reduzir pré e pós-carga, se PA permitir.\n- Morfina IV (cautela).\n- Monitorização hemodinâmica e sintomática contínua.", category: "cardiologia", tags: ["eapc", "emergência", "tratamento"] },
  { id: "fc-gen-neurologia-001", front: "Quais são os critérios diagnósticos para Esclerose Múltipla, de acordo com McDonald (2017)?", back: "Diagnóstico requer:\n- 2 ou mais surtos e 2 ou mais lesões (sem evidência de disseminação no tempo e espaço)\n- 2 ou mais surtos e 1 lesão (exige disseminação no espaço ou tempo via RM ou novo surto)\n- 1 surto e 2 ou mais lesões (exige disseminação no tempo via RM ou novo surto)\n- 1 surto e 1 lesão (exige disseminação no espaço E tempo via RM ou novo surto)\n- Lesões típicas em RM, LCR com bandas oligoclonais, e excluir outras doenças.", category: "neurologia", tags: ["esclerose-multipla", "mcdonald"] },
  { id: "fc-gen-neurologia-002", front: "Qual é a conduta inicial para um paciente com estado de mal epiléptico convulsivo refratário?", back: "Após falha de benzodiazepínicos (1ª linha), a conduta envolve:\n- 2ª Linha (após 5-10 min): Fosfenitoína intravenosa (20 mg EF/kg) ou Ácido Valproico (40 mg/kg IV) ou Leveticaretam (60 mg/kg IV).\n- Monitorização contínua de EEG.\n- Avaliar causas subjacentes e corrigir distúrbios metabólicos/hidroeletrolíticos.", category: "neurologia", tags: ["epilepsia", "mal-epiléptico"] },
  { id: "fc-gen-neurologia-003", front: "Quais os principais critérios para indicação de trombectomia mecânica no AVC isquêmico agudo?", back: "Critérios incluem:\n- AVC isquêmico agudo, \n- Oclusão de grande vaso (carótida interna, cerebral média M1 ou M2).\n- NIHSS ≥ 6, Rankin pré-AVC 0-1.\n- Janela terapêutica: até 6 horas (ou até 24h em casos selecionados com imagem de perfusão).\n- Idade ≥ 18 anos.", category: "neurologia", tags: ["avc", "trombectomia"] },
  { id: "fc-gen-neurologia-004", front: "Qual a dose e via de administração da piridostigmina no tratamento inicial da miastenia gravis?", back: "A dose inicial de piridostigmina para Miastenia Gravis é geralmente:\n- 30-60 mg via oral, a cada 4-6 horas.\n- A dose é ajustada individualmente, baseando-se na resposta clínica e nos efeitos adversos (ex: cólicas abdominais, diarreia, salivação excessiva).\n- É um inibidor da acetilcolinesterase, aumentando a disponibilidade de acetilcolina na placa motora.", category: "neurologia", tags: ["miastenia-gravis", "farmacologia"] },
  { id: "fc-gen-neurologia-005", front: "Quais são os principais achados do líquor (LCR) na Síndrome de Guillain-Barré (SGB)?", back: "Os achados típicos no LCR na SGB incluem:\n- Dissociação albumino-citológica: aumento significativo da proteína total (geralmente > 0,5 g/L) sem aumento correspondente da contagem de células (geralmente < 10 células/mm³).\n- Ausência de pleocitose significativa é crucial para o diagnóstico.\n- Este padrão é mais evidente após a primeira semana do início dos sintomas.", category: "neurologia", tags: ["guillain-barré", "lcr"] },
  { id: "fc-gen-cardiologia-054", front: "Quais os principais exames complementares para o diagnóstico e avaliação da insuficiência cardíaca com fração de ejeção reduzida (ICFEr)?", back: "- ECG: Avalia arritmias, hipertrofias, isquemia.\n- Radiografia de tórax: Cardiomegalia, congestão pulmonar.\n- Ecocardiograma transtorácico: Essencial para confirmar disfunção ventricular, FEVE, pressões de enchimento.\n- BNP/NT-proBNP: Marcadores de estresse miocárdico, úteis no diagnóstico e prognóstico.\n- Exames laboratoriais de rotina: Hemograma, função renal, eletrólitos, função hepática, tireoide, glicemia.", category: "cardiologia", tags: ["ic", "diagnóstico", "exames"] },
  { id: "fc-gen-cardiologia-055", front: "Qual a dose inicial e o esquema de titulação para sacubitril/valsartana em pacientes com ICFEr sintomática?", back: "Dose inicial: 49/51 mg (sacubitril/valsartana) duas vezes ao dia.\nTitulação: Dobrar a dose a cada 2-4 semanas, conforme tolerância, até atingir a dose-alvo de 97/103 mg duas vezes ao dia.\nMonitorar: Pressão arterial e função renal durante a titulação.", category: "cardiologia", tags: ["ic", "fármacos", "doses"] },
  { id: "fc-gen-cardiologia-056", front: "Critérios diagnósticos para Síndrome Coronariana Aguda sem Supradesnivelamento do Segmento ST (SCASSST/Angina Instável)?", back: "- Dor torácica isquêmica em repouso > 20 min ou \n- Dor torácica de início recente (classe III CCS em 2 meses) ou \n- Angina previamente estável que se torna mais frequente, intensa, prolongada, ou com menor esforço (angina crescendô).\n- Sem supradesnivelamento persistente do ST no ECG.\n- Trocadilhos podem estar elevados (SCASSST) ou normais (angina instável).", category: "cardiologia", tags: ["scassst", "diagnóstico", "isquemia"] },
  { id: "fc-gen-cardiologia-057", front: "Qual a conduta inicial para um paciente com infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST)?", back: "- Medidas gerais: O2 (se sat O2 < 90%), acesso venoso, monitorização cardíaca.\n- Antiplaquetários: AAS 150-300mg VO/mastigável + Clopidogrel (300-600mg) ou Prasugrel (60mg) ou Ticagrelor (180mg).\n- Anticoagulação: Heparina não fracionada (bolus + infusão) ou Enoxaparina.\n- Nitratos: Sublingual/IV (se dor persistente, congestão, PA elevada).\n- Analgesia: Morfina (se dor refratária).\n- Estratégia de reperfusão: Angioplastia primária (idealmente < 90-120 min) OU Trombólise (se angioplastia não disponível em tempo hábil).", category: "cardiologia", tags: ["iam", "conduta", "reperfusão"] },
  { id: "fc-gen-cardiologia-058", front: "Quais os principais efeitos adversos da amiodarona?", back: "- Tireoidianos: Hipo ou hipertireoidismo.\n- Pulmonares: Fibrose pulmonar (grave).\n- Hepáticos: Elevação de transaminases, hepatite.\n- Neurológicos: Neuropatia periférica, ataxia.\n- Oftalmológicos: Microdepósitos corneanos, neurite óptica.\n- Cutâneos: Fotossensibilidade (coloração azul-acinzentada da pele).\n- Cardíacos: Bradicardia, bloqueios atrioventriculares, prolongamento do QT.", category: "cardiologia", tags: ["amiodarona", "antiarrítmico", "efeitos adversos"] },
  { id: "fc-gen-cardiologia-059", front: "Qual a classificação da hipertensão arterial sistêmica (HAS) em adultos, segundo a SBC?", back: "- Ótima: PAS < 120 e PAD < 80 mmHg.\n- Normal: PAS 120-129 e/ou PAD 80-84 mmHg.\n- Limítrofe: PAS 130-139 e/ou PAD 85-89 mmHg.\n- Estágio 1: PAS 140-159 e/ou PAD 90-99 mmHg.\n- Estágio 2: PAS 160-179 e/ou PAD 100-109 mmHg.\n- Estágio 3: PAS ≥ 180 e/ou PAD ≥ 110 mmHg.", category: "cardiologia", tags: ["has", "classificação", "sbc"] },
  { id: "fc-gen-cardiologia-060", front: "Qual a meta de LDL-c para pacientes de muito alto risco cardiovascular?", back: "A meta de LDL-c para pacientes de muito alto risco cardiovascular (ex: doença aterosclerótica estabelecida, diabetes com dano em órgão-alvo ou 3+ fatores de risco, doença renal crônica grave) é < 50 mg/dL, ou uma redução de pelo menos 50% em pacientes que não atingem a meta apesar de dose máxima tolerada de estatina.", category: "cardiologia", tags: ["dislipidemia", "ldl-c", "metas"] },
  { id: "fc-gen-cardiologia-061", front: "Qual a principal diferença entre angina estável e infarto agudo do miocárdio?", back: "Angina Estável:\n- Dor torácica desencadeada por esforço ou estresse.\n- Alivia com repouso ou nitratos em menos de 5 minutos.\n- Sem elevação de biomarcadores cardíacos.\n\nInfarto Agudo do Miocárdio:\n- Dor torácica geralmente mais intensa, prolongada (> 20 min) e em repouso.\n- Não alivia com repouso ou nitratos.\n- Elevação e queda de biomarcadores cardíacos (troponinas) com pelo menos um valor acima do percentil 99 do limite superior de referência.", category: "cardiologia", tags: ["angina", "iam", "diferenças"] },
  { id: "fc-gen-cardiologia-062", front: "Quais os principais pilares do tratamento medicamentoso da insuficiência cardíaca com fração de ejeção reduzida (ICFEr)?", back: "- Betabloqueadores (BB): Carvedilol, succinato de metoprolol, bisoprolol.\n- Inibidores da SGLT2 (iSGLT2): Dapagliflozina, empagliflozina.\n- Inibidores da ECA (IECA) ou Bloqueadores do Receptor de Angiotensina (BRA): Enalapril, losartana.\n- Antagonistas do Receptor de Mineralocorticoide (ARM): Espironolactona, eplerenona.\n- Inibidores da Neprilisina e Receptor da Angiotensina (INRA): Sacubitril/valsartana (substitui IECA/BRA).\nEsses são os 'quatro pilares' da terapia modificadora de doença, quando indicados e tolerados.", category: "cardiologia", tags: ["icfer", "tratamento", "fármacos"] },
  { id: "fc-gen-cardiologia-063", front: "Quais as indicações para anticoagulação oral em pacientes com fibrilação atrial (FA)?", back: "Baseado no escore CHA2DS2-VASc:\n- CHA2DS2-VASc ≥ 2 em homens ou ≥ 3 em mulheres: Anticoagulação oral recomendada (DOACs ou Varfarina).\n- CHA2DS2-VASc = 1 em homens ou = 2 em mulheres: Anticoagulação oral deve ser considerada.\n- CHA2DS2-VASc = 0 em homens ou = 1 em mulheres: Geralmente não é benéfica a anticoagulação.", category: "cardiologia", tags: ["fa", "anticoagulação", "chads2vasc"] },
  { id: "fc-gen-cardiologia-064", front: "Qual o significado de um escore de TIMI de 0-2 em pacientes com SCASSST/Angina Instável?", back: "Um escore de TIMI de 0-2 em SCASSST/Angina Instável indica baixo risco de eventos cardíacos maiores em 14 dias.\n- 0-1 ponto: Baixo risco.\n- 2 pontos: Baixo a risco intermediário.\nPacientes com TIMI baixo-intermediário podem ser manejados com estratégia conservadora inicial, incluindo terapia anti-isquêmica otimizada e estratificação invasiva tardia se indicado.", category: "cardiologia", tags: ["timi", "risco", "scassst"] },
  { id: "fc-gen-cardiologia-065", front: "Qual a conduta para reversão de taquicardia supraventricular (TSV) com sinais de instabilidade hemodinâmica?", back: "Cardioversão elétrica sincronizada imediata.\n- Em adultos, geralmente inicia-se com 50-100 Joules (ondas monofásicas) ou 50-70 Joules (ondas bifásicas).\n- Sedação deve ser considerada se o paciente estiver consciente e o tempo permitir, mas não deve atrasar a cardioversão em caso de instabilidade grave.", category: "cardiologia", tags: ["tsv", "taquicardia", "cardioversão"] },
  { id: "fc-gen-cardiologia-066", front: "Quais as principais causas de parada cardíaca na emergência (os 'Hs' e 'Ts')?", back: "5 Hs:\n- Hipóxia\n- Hipovolemia\n- Hipotermia\n- Hipo/Hipercalemia (outros distúrbios metabólicos)\n- Hidrogênio íon (acidose)\n\n5 Ts:\n- Tensão pneumotórax\n- Tamponamento cardíaco\n- Tóxicos\n- Trombose coronariana (IAM)\n- Trombose pulmonar (TEP maciço)", category: "cardiologia", tags: ["parada", "emergência", "causas"] },
  { id: "fc-gen-cardiologia-067", front: "Quais os critérios ecocardiográficos diagnósticos de estenose aórtica grave?", back: "- Área valvar aórtica (AVA) < 1,0 cm².\n- Gradiente de pressão médio transvalvar aórtico (DPm) ≥ 40 mmHg.\n- Velocidade máxima do fluxo aórtico (Vmax) ≥ 4,0 m/s.\n- Em pacientes com disfunção ventricular e baixo fluxo/baixo gradiente, calcular o índice de área valvar (AVA indexada < 0,6 cm²/m²) ou fazer teste de estresse com dobutamina.", category: "cardiologia", tags: ["estenose aórtica", "diagnóstico", "eco"] },
  { id: "fc-gen-cardiologia-068", front: "Qual a diferença entre a classificação de Killip e Forrester no choque cardiogênico?", back: "Killip (IAM):\n- Classe I: Sem sinais de IC.\n- Classe II: Sinais de IC leve/moderada (B3, creptantes em < 50% dos campos pulmonares, aumento da PVC).\n- Classe III: Edema agudo de pulmão (creptantes em > 50% dos campos pulmonares).\n- Classe IV: Choque cardiogênico.\n\nForrester (cateter de Swan-Ganz):\n- Classe I (Normal): PCVE < 18 mmHg e IC < 2,2 L/min/m².\n- Classe II (Congestão): PCVE ≥ 18 mmHg e IC ≥ 2,2 L/min/m².\n- Classe III (Hipoperfusão): PCVE < 18 mmHg e IC < 2,2 L/min/m².\n- Classe IV (Choque Cardiogênico): PCVE ≥ 18 mmHg e IC < 2,2 L/min/m².", category: "cardiologia", tags: ["choque", "classificação", "iam"] },
  { id: "fc-gen-cardiologia-069", front: "Qual a dose e o regime de clopidogrel para pacientes submetidos a intervenção coronariana percutânea (ICP) com SCA?", back: "Em pacientes com SCA submetidos à ICP:\n- Dose de ataque: 300-600 mg VO (preferencialmente 600 mg se não houver alto risco de sangramento e ICP será realizada rapidamente).\n- Dose de manutenção: 75 mg VO uma vez ao dia.\n- Duração: Geralmente 12 meses em combinação com AAS (Terapia Antiplaquetária Dupla - TAPD), considerando risco isquêmico vs. risco hemorrágico do paciente.", category: "cardiologia", tags: ["sac", "icp", "antiplaquetário"] },
  { id: "fc-gen-cardiologia-070", front: "Quais são os critérios para o diagnóstico de endocardite infecciosa segundo os Critérios de Duke Modificados?", back: "Critérios Maiores:\n- Hemocultura positiva para EI.\n- Evidência de envolvimento endocárdico (ecocardiograma).\n\nCritérios Menores:\n- Predisposição cardíaca ou uso de drogas IV.\n- Febre ≥ 38°C.\n- Fenômenos vasculares (êmbolos, infartos, aneurismas micóticos, hemorragia intracraniana, lesões de Janeway).\n- Fenômenos imunológicos (glomerulonefrite, nódulos de Osler, manchas de Roth, fator reumatoide).\n- Evidência microbiológica (hemocultura inconsistente com critério maior).\n\nDiagnóstico: 2 Maiores OU 1 Maior + 3 Menores OU 5 Menores.", category: "cardiologia", tags: ["endocardite", "diagnóstico", "duke"] },
  { id: "fc-gen-cardiologia-071", front: "Em quais situações clínicas a rivaroxabana é contraindicada ou deve ser usada com extrema cautela?", back: "- Sangramento ativo clinicamente significativo (ex: úlcera péptica ativa, hemorragia cerebral recente).\n- Doença hepática associada a coagulopatia e risco de sangramento clinicamente relevante.\n- Glicemia elevada ou diabetes mellitus não controlados (relativo).\n- Presença de lesões ou condições com risco significativo de sangramento maior (ex: malformação arteriovenosa).\n- Gravidez e lactação.\n- Insuficiência renal grave (ClCr < 15 mL/min).\n- Uso concomitante de indutores potentes de CYP3A4/P-gp (ex: rifampicina, fenitoína, carbamazepina, Erva-de-São-João).", category: "cardiologia", tags: ["doac", "rivaroxabana", "contraindicações"] },
  { id: "fc-gen-cardiologia-072", front: "Qual o tratamento farmacológico para a crise hipertensiva (urgência e emergência hipertensiva)?", back: "Urgência Hipertensiva (sem lesão de órgão-alvo agudo):\n- Redução gradual da PA em 24-48h.\n- Medicamentos orais: Captopril, clonidina, anlodipino, losartana.\n\nEmergência Hipertensiva (com lesão de órgão-alvo agudo):\n- Redução imediata da PA com medicação EV.\n- Redução da PAM em 20-25% na 1a hora.\n- Fármacos: Nitroprussiato de sódio, labetalol, nicardipino, esmolol, hidralazina (em gestANTES).\n- Seleção do fármaco depende da lesão de órgão-alvo (ex: EAP - furosemida + nitrato; Dissecção de Aorta - betabloqueador + nitroprussiato).", category: "cardiologia", tags: ["crise hipertensiva", "tratamento", "emergência"] },
  { id: "fc-gen-cardiologia-073", front: "Qual a diferença entre choque cardiogênico e choque hipovolêmico em relação aos parâmetros hemodinâmicos?", back: "Choque Cardiogênico:\n- Débito Cardíaco (DC) ↓\n- Pressão Capilar Pulmonar em Cunha (PCPc) ↑\n- Resistência Vascular Sistêmica (RVS) ↑\n- Pressão Venosa Central (PVC) ↑\n\nChoque Hipovolêmico:\n- Débito Cardíaco (DC) ↓\n- Pressão Capilar Pulmonar em Cunha (PCPc) ↓\n- Resistência Vascular Sistêmica (RVS) ↑\n- Pressão Venosa Central (PVC) ↓", category: "cardiologia", tags: ["choque", "hemodinâmica", "diferenças"] },
  { id: "fc-gen-cardiologia-074", front: "Quais as indicações para o implante de um marca-passo cardíaco definitivo?", back: "- Bradicardia sintomática persistente.\n- Bloqueio atrioventricular (BAV) de 2º grau Mobitz II e 3º grau, mesmo assintomático.\n- Disfunção do nó sinusal sintomática (doença do nó sinusal).\n- BAV de 2º grau Mobitz I sintomático.\n- BAV após IAM (depende da localização e persistência).\n- BAV congénito.\n- Síndrome de taquicardia-bradicardia.\n- Prevenção de FA em alguns casos.", category: "cardiologia", tags: ["marcapasso", "bradicardia", "indicações"] },
  { id: "fc-gen-cardiologia-075", front: "Qual o papel do ecocardiograma transesofágico (ETE) no diagnóstico de doenças cardíacas?", back: "- Detecção de trombos em átrio esquerdo (particularmente na auriculeta) antes de cardioversão de FA.\n- Avaliação de endocardite infecciosa (vegetações pequenas, abscessos, fístulas).\n- Diagnóstico e quantificação de valvopatias complexas.\n- Detecção de comunicações interatriais/forame oval patente.\n- Melhor visualização de estruturas posteriores do coração e aorta torácica.\n- Guia em procedimentos intervencionistas.", category: "cardiologia", tags: ["eco", "ete", "diagnóstico"] },
  { id: "fc-gen-cardiologia-076", front: "Quais os principais efeitos terapêuticos dos nitratos na doença arterial coronariana?", back: "- Vasodilatação venosa: Reduz o retorno venoso (pré-carga), diminuindo a demanda de oxigênio do miocárdio.\n- Vasodilatação arterial: Em doses mais altas, reduz a pós-carga (diminui resistência vascular sistêmica), também diminuindo a demanda.\n- Vasodilatação coronariana: Alivia espasmos coronarianos e melhora o fluxo para áreas isquêmicas (particularmente vasos epicárdicos maiores).", category: "cardiologia", tags: ["nitratos", "dac", "fármacos"] },
  { id: "fc-gen-cardiologia-077", front: "Quais os critérios para o diagnóstico de diabetes mellitus gestacional (DMG) segundo a SBP/MS-Brasil?", back: "Realiza-se teste de tolerância à glicose oral (TTGO) com 75g de glicose entre 24-28 semanas de gestação. O diagnóstico de DMG é feito se um ou mais valores forem iguais ou superiores a:\n- Jejum: ≥ 92 mg/dL\n- 1 hora: ≥ 180 mg/dL\n- 2 horas: ≥ 153 mg/dL\n\nAlternativamente, se Glicemia em Jejum no 1º trimestre ≥ 92 mg/dL e < 126 mg/dL já pode configurar DMG.", category: "cardiologia", tags: ["dmg", "diabetes", "gestação"] },
  { id: "fc-gen-cardiologia-078", front: "Quais são as principais medidas não farmacológicas recomendadas para pacientes com hipertensão arterial sistêmica (HAS)?", back: "- Redução do peso corporal (IMC entre 18,5 e 24,9 kg/m²).\n- Dieta saudável (Dash, Mediterrânea, ricas em frutas/vegetais/fibras, baixo sódio, gorduras saturadas/trans).\n- Restrição de sódio (idealmente < 2 g/dia de sódio ou < 5 g/dia de cloreto de sódio).\n- Consumo moderado de álcool (até 1 dose/dia para mulheres e 2 doses/dia para homens).\n- Atividade física regular (aeróbica moderada: 150 min/sem ou intensa: 75 min/sem, combinada com treinamento de força).\n- Abandono do tabagismo.", category: "cardiologia", tags: ["has", "não-farmacológico", "estilo de vida"] },
  { id: "fc-gen-pneumologia-031", front: "Quais os critérios diagnósticos para asma em adultos, segundo a GINA 2024?", back: "Os critérios incluem:\n- História de sintomas respiratórios variáveis (sibilância, dispneia, aperto no peito, tosse), que variam em frequência e intensidade.\n- Evidência de limitação variável do fluxo aéreo expiratório, seja por:\n  - Broncodilatação reversível (aumento do VEF1 > 12% E > 200mL pós-broncodilatador).\n  - Variação diária excessiva do PFE ou VEF1.\n  - Melhoria significativa após 4 semanas de tratamento anti-inflamatório.", category: "pneumologia", tags: ["asma", "diagnóstico", "gina"] },
  { id: "fc-gen-pneumologia-032", front: "Qual a classificação da DPOC quanto à gravidade da limitação do fluxo aéreo, segundo a GOLD 2024?", back: "A classificação GOLD é baseada no VEF1 pós-broncodilatador:\n- GOLD 1 (Leve): VEF1 ≥ 80% do previsto.\n- GOLD 2 (Moderada): VEF1 50-79% do previsto.\n- GOLD 3 (Grave): VEF1 30-49% do previsto.\n- GOLD 4 (Muito grave): VEF1 < 30% do previsto.", category: "pneumologia", tags: ["dpoc", "gold", "classificação"] },
  { id: "fc-gen-pneumologia-033", front: "Qual a dose inicial recomendada de salmeterol para DPOC?", back: "Salmeterol é um LABA que geralmente é usado em combinação. A dose recomendada é de 50 mcg, 2 vezes ao dia, por via inalatória (geralmente em associação com corticosteroide inalatório).", category: "pneumologia", tags: ["dpoc", "farmacologia", "salmeterol"] },
  { id: "fc-gen-pneumologia-034", front: "Qual o esquema de tratamento para tuberculose pulmonar sensível a drogas no Brasil (adultos)?", back: "O esquema padrão é de 6 meses:\n- Fase intensiva (2 meses): Rifampicina (10 mg/kg, máx. 600 mg), Isoniazida (5-10 mg/kg, máx. 300 mg), Pirazinamida (20-30 mg/kg, máx. 2 g) e Etambutol (15-25 mg/kg, máx. 1,6 g) diariamente.\n- Fase de manutenção (4 meses): Rifampicina e Isoniazida diariamente.", category: "pneumologia", tags: ["tuberculose", "tratamento", "brasil"] },
  { id: "fc-gen-pneumologia-035", front: "Quais os principais fatores de risco para desenvolver câncer de pulmão?", back: "Os principais fatores de risco são:\n- Tabagismo (ativo e passivo).\n- Exposição a asbesto, radônio, arsênio, cromo, níquel, cádmio, éteres de clorometila.\n- Histórico familiar de câncer de pulmão.\n- Doenças pulmonares crônicas (ex: fibrose pulmonar, DPOC grave).\n- Poluição do ar.", category: "pneumologia", tags: ["câncer de pulmão", "fatores de risco", "oncologia"] },
  { id: "fc-gen-pneumologia-036", front: "Qual a dose de manutenção de budesonida inalatória para asma persistente moderada em adultos?", back: "Para asma persistente moderada, a dose de budesonida inalatória é geralmente de 400-800 mcg/dia (dividida em 2 doses), ajustada conforme a resposta clínica do paciente. Pode ser administrada via inalador de pó seco ou aerossol dosimetrado.", category: "pneumologia", tags: ["asma", "budesonida", "farmacologia"] },
  { id: "fc-gen-pneumologia-037", front: "Quais os escores utilizados para avaliação de risco de morte em pneumonia adquirida na comunidade (PAC)?", back: "Os principais escores são:\n- CURB-65: Confusão, Ureia (>7 mmol/L), Frequência respiratória (≥30 irpm), Pressão sanguínea (PAS <90 mmHg ou PAD ≤60 mmHg), Idade (≥65 anos).\n- PSI (Pneumonia Severity Index)/PORT: Mais detalhado, com 20 variáveis, estratifica o risco em 5 classes. Frequentemente usado para estratificação ambulatorial versus hospitalar.", category: "pneumologia", tags: ["pneumonia", "curb-65", "psi"] },
  { id: "fc-gen-pneumologia-038", front: "Qual a terapia empírica de primeira linha para PAC em paciente internado em enfermaria (não UTI), sem fatores de risco para pseudomonas ou MRSA?", back: "A terapia empírica recomendada é:\n- Betalactâmico (ex: ceftriaxona 1-2g EV/IM 24h ou ampicilina/sulbactam 3g EV 6/8h) + macrolídeo (ex: azitromicina 500mg EV 24h).\nOU\n- Fluorquinolona respiratória (ex: levofloxacino 750mg EV 24h ou moxifloxacino 400mg EV 24h).", category: "pneumologia", tags: ["pneumonia", "antibiótico", "pac"] },
  { id: "fc-gen-pneumologia-039", front: "Quais as indicações de ventilação mecânica não invasiva (VMNI) em exacerbação aguda de DPOC?", back: "As indicações de VMNI incluem:\n- Acidose respiratória (pH < 7,35, PaCO2 > 45 mmHg).\n- Dispneia grave com uso de musculatura acessória e/ou movimento abdominal paradoxal.\n- Frequência respiratória > 25 irpm com insuficiência respiratória moderada a grave.\n- Hipoxemia apesar de oxigenoterapia suplementar.", category: "pneumologia", tags: ["dpoc", "vm", "vmni"] },
  { id: "fc-gen-pneumologia-040", front: "Qual o principal critério para diagnóstico de doença do refluxo gastroesofágico (DRGE) relacionada a sintomas respiratórios crônicos?", back: "O principal critério é a resposta terapêutica. A melhora dos sintomas respiratórios (tosse crônica, sibilância) após um teste terapêutico com inibidores de bomba de prótons (IBP) em dose dupla por 8 a 12 semanas, na ausência de outras causas pulmonares ou otorrinolaringológicas, sugere fortemente a DRGE como fator contribuinte.", category: "pneumologia", tags: ["drge", "tosse crônica", "diagnóstico"] },
  { id: "fc-gen-pneumologia-041", front: "Qual o objetivo da saturação de oxigênio (SpO2) em pacientes com exacerbação de DPOC?", back: "O objetivo é manter a SpO2 entre 88-92% para evitar hipoxemia grave, mas também para prevenir a supressão do drive respiratório e hipercapnia induzida por oxigênio. Iniciar com fluxo baixo de oxigênio e titular cuidadosamente.", category: "pneumologia", tags: ["dpoc", "oxigenoterapia", "spo2"] },
  { id: "fc-gen-pneumologia-042", front: "Qual a principal causa infecciosa de bronquiolite em lactentes?", back: "A principal causa infecciosa de bronquiolite em lactentes é o Vírus Sincicial Respiratório (VSR), responsável por 60-80% dos casos. Outros agentes incluem rinovírus, parainfluenza e adenovírus.", category: "pneumologia", tags: ["bronquiolite", "pediatria", "vsr"] },
  { id: "fc-gen-pneumologia-043", front: "Quais os principais efeitos adversos dos corticosteroides inalatórios (CI) em doses elevadas?", back: "Os efeitos adversos podem incluir:\n- Candidíase orofaríngea (sapinho).\n- Disfonia.\n- Tosse.\n- Em doses muito elevadas e uso prolongado: supressão adrenal, osteoporose, catarata, glaucoma e, em crianças, retardo do crescimento (embora o impacto seja mínimo na dose terapêutica).", category: "pneumologia", tags: ["asma", "farmacologia", "corticosteroide"] },
  { id: "fc-gen-pneumologia-044", front: "Qual a indicação e dose do omalizumabe para asma alérgica grave?", back: "Omalizumabe é indicado para asma alérgica grave, não controlada com CI de alta dose e LABA, com IgE sérica total elevada. A dose (150-375 mg a cada 2 ou 4 semanas) é determinada com base no peso corporal e no nível de IgE sérica, conforme tabela do fabricante.", category: "pneumologia", tags: ["asma", "omalizumabe", "biológicos"] },
  { id: "fc-gen-pneumologia-045", front: "Quais os critérios laboratóriais para diagnóstico de síndrome do desconforto respiratório agudo (SDRA)?", back: "Os critérios da definição de Berlin incluem:\n- Início dentro de 1 semana de uma injúria clínica conhecida.\n- Opacidades bilaterais na radiografia ou TC de tórax, não totalmente explicadas por derrames, colapso lobar ou nodularização.\n- Insuficiência respiratória não totalmente explicada por insuficiência cardíaca ou sobrecarga hídrica.\n- Relação PaO2/FiO2 ≤ 300 mmHg, com PEEP ou CPAP ≥ 5 cmH2O.\n  - Leve: PaO2/FiO2 201-300 mmHg.\n  - Moderada: PaO2/FiO2 101-200 mmHg.\n  - Grave: PaO2/FiO2 ≤ 100 mmHg.", category: "pneumologia", tags: ["sdra", "diagnóstico", "berlin"] },
  { id: "fc-gen-pneumologia-046", front: "Qual a principal alteração radiológica na pneumonia por Pneumocystis jirovecii em pacientes com HIV?", back: "A principal alteração é o infiltrado intersticial bilateral difuso de pequena monta ou perihilar, que pode progredir para infiltrado alveolar confluente. Cistos e pneumotórax espontâneo também podem ser vistos. É frequentemente desproporcional à gravidade da hipoxemia.", category: "pneumologia", tags: ["pneumonia", "hiv", "pneumocystis"] },
  { id: "fc-gen-pneumologia-047", front: "Qual o mecanismo de ação da teofilina no tratamento da DPOC e asma?", back: "A teofilina atua principalmente como inibidor não seletivo da fosfodiesterase, aumentando o AMP cíclico intracelular e promovendo broncodilatação. Também possui efeitos anti-inflamatórios e imunomoduladores, como inibição da adenosina e melhora da contratilidade diafragmática. Seu uso é limitado devido ao baixo índice terapêutico e efeitos adversos.", category: "pneumologia", tags: ["dpoc", "asma", "teofilina"] },
  { id: "fc-gen-pneumologia-048", front: "Quais os principais achados na espirometria de pacientes com fibrose pulmonar idiopática (FPI)?", back: "A espirometria na FPI tipicamente mostra um padrão restritivo:\n- Redução do VEF1 (Volume Expiratório Forçado no 1º segundo).\n- Redução da CVF (Capacidade Vital Forçada).\n- Relação VEF1/CVF normal ou aumentada (> 0,7).\n- Além disso, há diminuição da capacidade de difusão de monóxido de carbono (DLCO).", category: "pneumologia", tags: ["fpi", "espirometria", "doença intersticial"] },
  { id: "fc-gen-pneumologia-049", front: "Qual a dose de prednisolona oral recomendada para exacerbação de asma em adultos?", back: "A dose recomendada de prednisolona oral para exacerbação leve a moderada de asma em adultos é de 40-50 mg/dia em dose única ou dividida, por um período de 5-7 dias, sem necessidade de desmame se o curso for curto.", category: "pneumologia", tags: ["asma", "exacerbação", "corticosteroide"] },
  { id: "fc-gen-pneumologia-050", front: "Quais os três pilares do tratamento não farmacológico da DPOC clinicamente estável?", back: "Os três pilares são:\n1. Cessação do tabagismo: É a intervenção mais eficaz para retardar a progressão da doença.\n2. Reabilitação pulmonar: Melhora a capacidade de exercício, dispneia e qualidade de vida.\n3. Vacinação: Contra influenza anualmente e pneumocócica (PCV13 e PPSV23) para reduzir infecções respiratórias.", category: "pneumologia", tags: ["dpoc", "não farmacológico", "estável"] },
  { id: "fc-gen-pneumologia-051", front: "Qual o agente etiológico mais comum da pneumonia aspirativa em pacientes com disfagia?", back: "A pneumonia aspirativa polimicrobiana é a mais comum, envolvendo bactérias gram-positivas (Streptococcus spp.) e gram-negativas entéricas (Klebsiella, Escherichia coli), além de anaeróbios orais (Peptostreptococcus, Fusobacterium, Bacteroides).", category: "pneumologia", tags: ["pneumonia", "aspirativa", "disfagia"] },
  { id: "fc-gen-pneumologia-052", front: "Qual é a dose usual de sulfato de magnésio intravenoso para exacerbação grave de asma em adultos?", back: "A dose usual é de 1,2 a 2 gramas de sulfato de magnésio, administrada por via intravenosa durante 20 a 30 minutos. É indicado para exacerbações graves ou com risco de vida, especialmente em pacientes que não respondem à terapia inicial com broncodilatadores e corticosteroides sistêmicos.", category: "pneumologia", tags: ["asma", "exacerbação", "sulfato de magnésio"] },
  { id: "fc-gen-pneumologia-053", front: "Quais os achados típicos de TCAR de tórax na bronquiectasia?", back: "Os achados típicos na TCAR de tórax incluem:\n- Dilatação brônquica (diâmetro brônquico maior que o da artéria adjacente – sinal do 'anel de sinete').\n- Falta de afilamento brônquico.\n- Espessamento das paredes brônquicas.\n- Impactação mucoide.\n- Cistos e abcesso brônquicos.\n- Áreas de 'ar aprisionado' e padrão em 'mosaico'.", category: "pneumologia", tags: ["bronquiectasia", "tcar", "achados"] },
  { id: "fc-gen-pneumologia-054", front: "Qual a indicação e a dose inicial de roflumilaste para DPOC?", back: "Roflumilaste é um inibidor da PDE-4 indicado para pacientes com DPOC grave a muito grave, bronquite crônica e histórico de exacerbações frequentes, para reduzir o risco de futuras exacerbações. A dose é de 500 mcg uma vez ao dia por via oral.", category: "pneumologia", tags: ["dpoc", "roflumilaste", "farmacologia"] },
  { id: "fc-gen-infectologia-001", front: "Quais são os critérios diagnósticos para Sífilis primária e secundária, conforme o Ministério da Saúde do Brasil?", back: "Sífilis Primária:\n- Úlcera geralmente única, indolor, de fundo limpo e bordas elevadas (cancro duro).\n- Linfonodos regionais aumentados, indolores, não supurativos.\n- Testes não treponêmicos (VDRL/RPR) geralmente reagentes (títulos baixos/médios).\n- Testes treponêmicos (FTA-Abs/TPHA) reagentes.\n\nSífilis Secundária:\n- Lesões cutâneo-mucosas polimorfas: roséolas, pápulas, lesões condilomatosas (condiloma plano) em áreas úmidas.\n- Linfadenopatia generalizada.\n- Testes não treponêmicos e treponêmicos reagentes, com VDRL/RPR geralmente em títulos elevados.", category: "infectologia", tags: ["sífilis", "rst", "diagnóstico"] },
  { id: "fc-gen-infectologia-002", front: "Qual o esquema de tratamento recomendado pelo MS-Brasil para Sífilis primária em gestantes, sem alergia à penicilina?", back: "Penicilina G Benzatina 2.400.000 UI, via intramuscular (IM), dose única (1.200.000 UI em cada glúteo).\n- Se a gestante foi tratada durante a gestação atual e os títulos persistem elevados ou não caem 4x em 3 meses, considerar retratamento com Penicilina G Benzatina 2.400.000 UI, IM, uma dose por semana, durante 3 semanas.", category: "infectologia", tags: ["sífilis", "gestação", "tratamento"] },
  { id: "fc-gen-infectologia-003", front: "Quais são os principais agentes etiológicos da meningite bacteriana aguda na população adulta (18-50 anos) e qual a antibioticoterapia empírica inicial recomendada?", back: "Agentes etiológicos:\n- Streptococcus pneumoniae\n- Neisseria meningitidis\n\nAntibioticoterapia empírica:\n- Ceftriaxona 2g IV a cada 12h OU Cefotaxima 2g IV a cada 4-6h.\n- Associar Dexametasona 10mg IV a cada 6h por 2-4 dias (iniciar antes ou junto com o antibiótico).\n- Adicionar Ampicilina 2g IV a cada 4h se houver suspeita de Listeria monocytogenes (imunocomprometidos, idosos >50 anos, alcoólatras, transplantados) ou se a idade for >50 anos.", category: "infectologia", tags: ["meningite", "antibioticoterapia", "bacteriana"] },
  { id: "fc-gen-infectologia-004", front: "Quais os principais fatores de risco para infecção urinária em pacientes do sexo feminino e quais os critérios diagnósticos para cistite?", back: "Fatores de risco:\n- Atividade sexual\n- Uso de diafragma ou espermicida\n- História prévia de ITU\n- Deficiência de estrogênio (pós-menopausa)\n- Diabetes mellitus\n\nCritérios diagnósticos para cistite:\n- Sintomas: disúria, polaciúria, urgência miccional, dor suprapúbica.\n- Urinálise: nitrito e/ou esterase leucocitária positiva, piúria (>10 leucócitos/mm³).\n- Urocultura: crescimento significativo de uropatógenos (>10^3 UFC/mL para sintomas típicos).", category: "infectologia", tags: ["itu", "cistite", "diagnóstico"] },
  { id: "fc-gen-infectologia-005", front: "Discorra sobre a profilaxia pré-exposição (PrEP) para HIV, incluindo indicações e esquema de uso no Brasil.", back: "Indicações (alto risco de exposição):\n- Pessoas com parcerias sorodiferentes (HIV+).\n- Múltiplas parcerias sexuais.\n- Sexo anal sem camisinha.\n- Episódios frequentes de ISTs.\n- Uso de substâncias psicoativas que comprometam o sexo seguro.\n\nEsquema de uso (PrEP diária):\n- Tenofovir disoproxil fumarato (TDF) 300mg + Emtricitabina (FTC) 200mg, 1 comprimido, via oral, uma vez ao dia, continuamente.\n- A PrEP sob demanda (2-1-1) pode ser uma alternativa para homens gays e outros HSH em alguns cenários específicos, com orientações precisas do Ministério da Saúde.", category: "infectologia", tags: ["hiv", "prep", "profilaxia"] },
  { id: "fc-gen-infectologia-006", front: "Quais são os critérios diagnósticos para Tuberculose pulmonar ativa em adultos, conforme o MS-Brasil?", back: "São critérios para Tuberculose pulmonar ativa:\n- Clínica sugestiva: tosse produtiva por mais de 3 semanas, febre, sudorese noturna, emagrecimento.\n- Radiografia de tórax com alterações compatíveis (cavitárias, infiltrados, etc.).\n- Baciloscopia de escarro positiva (pelo menos duas amostras ou uma amostra em paciente sintomático respiratório).\n- Teste rápido molecular para TB (TRM-TB) positivo (detecta Mycobacterium tuberculosis e resistência à rifampicina).\n- Cultura de escarro positiva para Mycobacterium tuberculosis.", category: "infectologia", tags: ["tuberculose", "pulmonar", "diagnóstico"] },
  { id: "fc-gen-infectologia-007", front: "Qual o tratamento padrão para Tuberculose pulmonar em adultos no Brasil, na fase intensiva e na fase de manutenção?", back: "Fase intensiva (2 meses):\n- Rifampicina (R) 150mg + Isoniazida (H) 75mg + Pirazinamida (Z) 400mg + Etambutol (E) 275mg.\n- Doses baseadas no peso do paciente, administradas diariamente.\n\nFase de manutenção (4 meses):\n- Rifampicina (R) 150mg + Isoniazida (H) 75mg.\n- Doses baseadas no peso do paciente, administradas diariamente.\n- O esquema totaliza 6 meses. Em casos especiais, pode haver esquemas mais longos.", category: "infectologia", tags: ["tuberculose", "tratamento", "esquema"] },
  { id: "fc-gen-infectologia-008", front: "Quais os critérios para o diagnóstico de Sepse e Choque Séptico, de acordo com o Sepsis-3?", back: "Sepse:\n- Infecção suspeita ou confirmada\n- Aumento agudo de ≥ 2 pontos no escore SOFA (Sequential Organ Failure Assessment)\n\nChoque Séptico:\n- Sepse com hipotensão persistente (PAM < 65 mmHg) requerendo vasopressores para manter a PAM ≥ 65 mmHg\n- Lactato sérico > 2 mmol/L (18 mg/dL) APÓS ressuscitação volêmica adequada\n- Apesar da ressuscitação volêmica, o paciente permanece hipoperfundido.", category: "infectologia", tags: ["sepse", "choque", "diagnóstico"] },
  { id: "fc-gen-infectologia-009", front: "Quais são as principais medidas do 'Pacote de 1 hora' para o manejo inicial da sepse, conforme Surviving Sepsis Campaign (2021)?", back: "1. Medir nível de lactato (e repetir se o lactato inicial for > 2 mmol/L).\n2. Obter hemoculturas (e outras culturas, se indicado) ANTES da administração de antibióticos.\n3. Administrar antibióticos de amplo espectro.\n4. Iniciar administração rápida de 30 mL/kg de cristaloides intravenosos para hipotensão ou lactato > 2 mmol/L.\n5. Iniciar vasopressores se o paciente estiver hipotenso durante ou após a ressuscitação volêmica para manter uma PAM ≥ 65 mmHg.", category: "infectologia", tags: ["sepse", "manejo", "campanha"] },
  { id: "fc-gen-infectologia-010", front: "Quais são os principais agentes etiológicos e o tratamento empírico para celulite não purulenta em pacientes sem fatores de risco para SARM?", back: "Principais agentes etiológicos:\n- Streptococcus pyogenes (beta-hemolítico do grupo A)\n- Staphylococcus aureus (sensível à meticilina)\n\nTratamento empírico (via oral):\n- Cefalexina 500 mg, de 6/6h por 5-10 dias OU\n- Amoxicilina + Clavulanato 875/125 mg, de 12/12h por 5-10 dias.\n- Em casos de alergia à penicilina/cefalosporina: Clindamicina 300-450 mg, de 6/6h por 5-10 dias.", category: "infectologia", tags: ["celulite", "dermatologia", "antibioticoterapia"] },
  { id: "fc-gen-infectologia-011", front: "Quais os critérios para diagnóstico de Dengue grave, segundo o MS-Brasil 2024?", back: "1. Sangramento grave (hematêmese, melena, hemorragia SNC, sangramento maciço).\n2. Choque (hipotensão, pulso rápido e fraco, enchimento capilar lento, pele fria e pegajosa).\n3. Acúmulo de líquidos com insuficiência respiratória (Derrame pleural, ascite, edema pulmonar).\n4. Comprometimento grave de órgãos (AST/ALT > 1000, comprometimento SNC, miocardite, insuficiência renal).", category: "infectologia", tags: ["dengue", "doenças tropicais", "diagnóstico"] },
  { id: "fc-gen-infectologia-012", front: "Qual o esquema antiviral preferencial para HIV em adultos naive, de acordo com o MS-Brasil 2024?", back: "Esquema preferencial inicial:\n- Tenofovir Alafenamida/Emtricitabina (TAF/FTC) + Dolutegravir (DTG).\nAlternativas (se indisponibilidade ou contraindicações):\n- Tenofovir Disoproxil Fumarato/Emtricitabina (TDF/FTC) + Dolutegravir (DTG).\n- Lamivudina (3TC) pode substituir Emtricitabina.", category: "infectologia", tags: ["hiv", "antirretroviral", "terapia"] },
  { id: "fc-gen-infectologia-013", front: "Qual a conduta inicial para choque séptico em adultos, segundo a Surviving Sepsis Campaign 2021?", back: "1. Administrar cristaloides intravenosos (30 mL/kg) nas primeiras 3 horas.\n2. Iniciar norepinefrina como vasopressor de primeira escolha se hipotensão persistente após reposição volêmica.\n3. Monitorar lactato, PVC e ScvO2 para guiar fluidoterapia e vasopressores.", category: "infectologia", tags: ["sepse", "choque", "emergência"] },
  { id: "fc-gen-infectologia-014", front: "Quais os principais agentes etiológicos da pneumonia adquirida na comunidade (PAC) em adultos sem comorbidades?", back: "1. Streptococcus pneumoniae (o mais comum).\n2. Mycoplasma pneumoniae.\n3. Chlamydophila pneumoniae.\n4. Vírus respiratórios (Influenza, Parainfluenza, RSV, Adenovírus).\n5. Legionella pneumophila.", category: "infectologia", tags: ["pneumonia", "etiologia", "pac"] },
  { id: "fc-gen-infectologia-015", front: "Qual a dose e via de administração da ceftriaxona para meningite bacteriana em adultos?", back: "- Dose: 2 g a cada 12 horas.\n- Via: Intravenosa (IV).\n- Duração: Varia conforme o agente etiológico, mas geralmente 7-14 dias.\n- Importante iniciar precocemente após suspeita clínica, idealmente após coleta de líquor.", category: "infectologia", tags: ["meningite", "antibiótico", "doses"] },
  { id: "fc-gen-infectologia-016", front: "Mecanismo de ação da vancomicina.", back: "A vancomicina é um glicopeptídeo que inibe a síntese da parede celular bacteriana. \nEla se liga firmemente ao terminal D-Ala-D-Ala dos precursores do peptidoglicano, impedindo a transpeptidação (ligação cruzada) e a transglicosilação, essenciais para a formação da parede. \nÉ um bactericida tempo-dependente.", category: "infectologia", tags: ["antibiótico", "mecanismo", "farmacologia"] },
  { id: "fc-gen-infectologia-017", front: "Critérios diagnósticos para endocardite infecciosa segundo Dukes modificados.", back: "- 2 critérios maiores OU\n- 1 critério maior e 3 menores OU\n- 5 critérios menores.\nCritérios maiores: Hemocultura positiva para EI típica, Evidência ecocardiográfica de envolvimento endocárdico.\nCritérios menores: Predisposição (cardiopatia, UDVI), Febre (>38ºC), Fenômenos vasculares, Fenômenos imunológicos, Evidência microbiológica.", category: "infectologia", tags: ["endocardite", "diagnóstico", "dukes"] },
  { id: "fc-gen-infectologia-018", front: "Qual a profilaxia pós-exposição (PEP) para HIV em acidentes com material biológico, segundo o MS-Brasil 2024?", back: "Esquema preferencial:\n- Tenofovir Disoproxil Fumarato (TDF) + Lamivudina (3TC) + Dolutegravir (DTG).\n- Iniciar idealmente nas primeiras 2 horas, até no máximo 72 horas pós-exposição.\n- Duração: 28 dias.\n- Necessita de avaliação de risco e acompanhamento médico.", category: "infectologia", tags: ["hiv", "pep", "profilaxia"] },
  { id: "fc-gen-infectologia-019", front: "Quais os principais efeitos adversos do Anfotericina B desoxicolato?", back: "1. Nefrotoxicidade (comum).\n2. Reações infusionais (febre, calafrios, cefaleia, mialgia).\n3. Anemia normocítica normocrômica.\n4. Hipocalemia, hipomagnesemia.\n5. Hepatotoxicidade (menos comum).", category: "infectologia", tags: ["antifúngico", "efeitos adversos", "farmacologia"] },
  { id: "fc-gen-infectologia-020", front: "Qual a conduta para sífilis primária em adultos não gestantes?", back: "- Penicilina G Benzatina 2.400.000 UI, dose única, intramuscular (IM).\n- Em caso de alergia à penicilina:\n  - Doxiciclina 100 mg, via oral, de 12/12h por 14 dias OU\n  - Ceftriaxona 1 g/dia IM ou IV por 10-14 dias (opção para gestantes alérgicas com dessensibilização contraindicada).", category: "infectologia", tags: ["sífilis", "ist", "tratamento"] },
  { id: "fc-gen-infectologia-021", front: "Principais agentes etiológicos da diarreia bacteriana invasiva em adultos.", back: "1. Salmonella spp (não typhi).\n2. Shigella spp.\n3. Campylobacter jejuni.\n4. Escherichia coli enteroinvasora (EIEC).\n5. Escherichia coli enterohemorrágica (EHEC).\n6. Clostridioides difficile (pós-antibióticos).", category: "infectologia", tags: ["diarreia", "bacteriana", "etiologia"] },
  { id: "fc-gen-infectologia-022", front: "Qual tratamento de escolha para o herpes zóster em adultos imunocompetentes com menos de 72h de erupção?", back: "- Aciclovir 800 mg, via oral, 5 vezes ao dia por 7 dias.\n- Alternativas: Valaciclovir 1000 mg, via oral, 3 vezes ao dia por 7 dias ou Fanciclovir 500 mg, via oral, 3 vezes ao dia por 7 dias.\n- Iniciar precocemente para reduzir dor e prevenir neuralgia pós-herpética.", category: "infectologia", tags: ["herpes zóster", "antiviral", "tratamento"] },
  { id: "fc-gen-infectologia-023", front: "Qual a principal indicação para profilaxia secundária de febre reumática?", back: "- Prevenção de novos surtos de febre reumática após um episódio agudo, geralmente com cardite.\n- Agente: Penicilina G Benzatina 1.200.000 UI IM a cada 21 dias.\n- Duração: Variável conforme o grau da doença cardíaca (5 anos, 10 anos ou até 21/30/40 anos).", category: "infectologia", tags: ["febre reumática", "profilaxia", "cardiologia"] },
  { id: "fc-gen-infectologia-024", front: "Quais os principais diagnósticos diferenciais da febre de origem indeterminada (FOI)?", back: "1. Infecções (TB, abcessos ocultos, EI, HIV, CMV, EBV).\n2. Neoplasias (linfomas, leucemias, carcinomas).\n3. Doenças reumatológicas/autoimunes (LES, AR, arterite temporal).\n4. Causas diversas (tireoidite, embolia pulmonar, medicamentosa, simulação).", category: "infectologia", tags: ["foi", "diagnóstico", "diferencial"] },
  { id: "fc-gen-infectologia-025", front: "Características clínicas da malária por Plasmodium falciparum grave.", back: "- Malaria cerebral (coma, convulsões).\n- Anemia grave (Hb < 5 g/dL ou Ht < 15%).\n- Insuficiência renal aguda (creatinina > 3 mg/dL).\n- SARA (SDRA).\n- Hipoglicemia, Acidose metabólica.\n- Icterícia grave, Choque, Hiperparasitemia (>10% de hemácias parasitadas).", category: "infectologia", tags: ["malária", "doenças tropicais", "urgência"] },
  { id: "fc-gen-infectologia-026", front: "Qual o tratamento empírico para abscesso cerebral em adultos imunocompetentes?", back: "- Ceftriaxona 2g IV a cada 12h OU Cefotaxima 2g IV a cada 4-6h.\n- Metronidazol 500mg IV a cada *8h (para anaeróbios).\n- Vancomicina 15-20 mg/kg IV a cada 8-12h (se suspeita de S. aureus resistente).\n- Duração: 4-8 semanas, guiado por melhora clínica e exames de imagem.", category: "infectologia", tags: ["abscesso", "snc", "antibiótico"] },
  { id: "fc-gen-infectologia-027", front: "Mecanismo de resistência bacteriana aos carbapenêmicos mais comum.", back: "- Produção de carbapenemases (enzimas que hidrolisam os carbapenêmicos).\n- As carbapenemases mais comuns são KPC (Klebsiella pneumoniae carbapenemase), NDM (New Delhi metallo-beta-lactamase) e OXA-48.", category: "infectologia", tags: ["resistência", "antibiótico", "mecanismo"] },
  { id: "fc-gen-infectologia-028", front: "Qual a dose e indicação do Oseltamivir para Influenza em adultos?", back: "- Indicação: Tratamento de infecção por Influenza em pacientes com sintomas graves, ou com fatores de risco para complicações, ou em até 48 horas do início dos sintomas.\n- Dose: 75 mg via oral, 2 vezes ao dia, por 5 dias.", category: "infectologia", tags: ["influenza", "antiviral", "doses"] },
  { id: "fc-gen-infectologia-029", front: "Tratamento de primeira linha para escabiose em adultos.", back: "- Permetrina 5% creme: Aplicar no corpo todo do pescoço para baixo, deixar por 8-14 horas e remover com banho. Repetir em 7 dias.\n- Alternativas: Ivermectina oral (200 mcg/kg em dose única, repetir em 7-14 dias) em casos refratários ou disseminados. Tratar contatos próximos.", category: "infectologia", tags: ["escabiose", "parasitose", "tratamento"] },
  { id: "fc-gen-infectologia-030", front: "Quais os critérios para internação hospitalar na celulite?", back: "1. Sinais de gravidade/Sepse (febre alta, taquicardia, hipotensão).\n2. Rápida progressão ou envolvimento de grandes áreas.\n3. Imunocomprometimento significativo.\n4. Falha no tratamento ambulatorial inicial.\n5. Celulite em áreas de risco (face com comprometimento ocular, mão/pé em diabéticos).", category: "infectologia", tags: ["celulite", "internação", "emergência"] },
  { id: "fc-gen-infectologia-031", front: "Agente etiológico e tratamento de primeira linha para ancilostomíase.", back: "- Agente etiológico: Ancylostoma duodenale e Necator americanus.\n- Tratamento: Albendazol 400 mg em dose única, via oral OU Mebendazol 100 mg 2x/dia por 3 dias ou 500 mg dose única.\n- Tratar anemia associada se presente.", category: "infectologia", tags: ["parasitose", "helmintíase", "tratamento"] },
  { id: "fc-gen-infectologia-032", front: "Qual a profilaxia para TB em contatos de bacilífero crianças com PPD positivo mas sem doença ativa?", back: "- Isoniazida, 10 mg/kg/dia (dose máxima de 300 mg/dia) por 6 meses.\n- Importante excluir tuberculose ativa antes de iniciar a profilaxia.", category: "infectologia", tags: ["tb", "profilaxia", "pediatria"] },
  { id: "fc-gen-infectologia-033", front: "Quais os principais agentes causadores de cistite não complicada em mulheres?", back: "1. Escherichia coli (mais de 80% dos casos).\n2. Klebsiella pneumoniae.\n3. Staphylococcus saprophyticus.\n4. Proteus mirabilis.", category: "infectologia", tags: ["cistite", "itu", "etiologia"] },
  { id: "fc-gen-infectologia-034", front: "Qual a conduta para mordedura de cão com lesão profunda na mão, em paciente não vacinado contra tétano?", back: "1. Limpeza rigorosa da ferida com água e sabão.\n2. Avaliar necessidade de desbridamento.\n3. Imunoglobulina Humana Antitetânica (IGHAT): 250 a 500 UI IM em local diferente da vacina.\n4. Vacina antitetânica: iniciar esquema completo (3 doses).\n5. Antibioticoprofilaxia: Amoxicilina com Clavulanato por 5-7 dias.", category: "infectologia", tags: ["mordedura", "tétano", "profilaxia"] },
  { id: "fc-gen-infectologia-035", front: "Qual o tratamento de primeira escolha para giardíase sintomática em adultos?", back: "- Metronidazol: 250 mg, 3 vezes ao dia, por 5 a 7 dias OU\n- Tinidazol: 2 g em dose única OU\n- Secnidazol: 2 g em dose única.\n- Paromomicina pode ser usada para gestantes.", category: "infectologia", tags: ["giardíase", "parasitose", "tratamento"] },
  { id: "fc-gen-nefrologia-001", front: "Quais os critérios para diagnóstico de Doença Renal Crônica (DRC) conforme KDIGO 2024?", back: "DRC é definida por anormalidades de estrutura ou função renal, presentes por >3 meses, com implicações para a saúde.\n• Marcadores diretos: albumina/creatinina urinária (ACR) >30 mg/g; Anormalidades no sedimento urinário; Anormalidades eletrolíticas ou outras devido a distúrbio tubular; Anormalidades histológicas (biópsia); Anormalidades estruturais de imagem; História de transplante renal.\n• Ou taxa de filtração glomerular (TFG) <60 mL/min/1.73m² (G3a-G5).", category: "nefrologia", tags: ["drc", "diagnóstico", "kdigo"] },
  { id: "fc-gen-nefrologia-002", front: "Qual a conduta inicial para hipercalemia grave (K >6.5 mEq/L ou alterações eletrocardiográficas)?", back: "1. Estabilização da membrana cardíaca: gluconato de cálcio 10% IV (10-20 mL em 5-10 min).\n2. Deslocamento de potássio para o intracelular: insulina regular 10 UI IV + glicose 50% 50 mL IV (se glicemia <250 mg/dL); ou agonistas beta-2. \n3. Remoção de potássio: furosemida 20-40 mg IV; resinas de troca iônica (ex: poliestirenossulfonato de sódio); ou diálise (em casos refratários ou muito graves).", category: "nefrologia", tags: ["hipercalemia", "emergência", "tratamento"] },
  { id: "fc-gen-nefrologia-003", front: "Quais são os principais fatores de risco para injúria renal aguda (IRA) em pacientes hospitalizados?", back: "• Sepsia\n• Choque (hipovolêmico, cardiogênico, séptico)\n• Uso de nefrotóxicos (ex: AINEs, contrastes iodados, aminoglicosídeos)\n• Cirurgia de grande porte (especialmente cardíacas)\n• Doença renal crônica pré-existente\n• Idade avançada\n• Diabetes mellitus, Hipertensão arterial sistêmica, Insuficiência cardíaca", category: "nefrologia", tags: ["ira", "risco", "hospitalização"] },
  { id: "fc-gen-nefrologia-004", front: "Qual o mecanismo de ação dos inibidores do SGLT2 (iSGLT2) na proteção renal?", back: "• Bloqueiam o cotransportador SGLT2 no túbulo contorcido proximal, aumentando a excreção urinária de glicose e sódio.\n• Reduzem a hiperfiltração glomerular (via feedback tubuloglomerular) diminuindo a pressão intraglomerular.\n• Diminuem a albumina na urina e o risco de progressão da DRC.\n• Efeitos anti-inflamatórios e antifibróticos renais diretos.", category: "nefrologia", tags: ["isglt2", "mecanismo", "proteção renal"] },
  { id: "fc-gen-nefrologia-005", front: "Quais os critérios modificados de RIFLE (Risk, Injury, Failure, Loss, End-stage kidney disease) para classificação de IRA?", back: "Os critérios RIFLE foram substituídos pelos critérios KDIGO para IRA, que incluem:\n• Aumento da creatinina sérica: \n  • Estágio 1: 1.5 a 1.9 vezes o valor basal OU aumento de ≥0.3 mg/dL.\n  • Estágio 2: 2.0 a 2.9 vezes o valor basal.\n  • Estágio 3: ≥3.0 vezes o valor basal OU creatinina sérica ≥4.0 mg/dL OU início de terapia de substituição renal. \n• Débito urinário:\n  • Estágio 1: <0.5 mL/kg/h por 6-12h.\n  • Estágio 2: <0.5 mL/kg/h por ≥12h.\n  • Estágio 3: <0.3 mL/kg/h por ≥24h OU anúria por ≥12h.", category: "nefrologia", tags: ["ira", "classificação", "kdigo"] },
  { id: "fc-gen-nefrologia-006", front: "Qual a indicação de tratamento de acidose metabólica grave (pH <7.1) no paciente com DRC?", back: "• Acidose metabólica grave refratária à correção da causa subjacente.\n• Bicarbonato de sódio IV é a principal intervenção para elevar o pH e bicarbonato sérico, com o objetivo de pH >7.2.\n• Na DRC avançada (G4-G5), pode ser necessária diálise.", category: "nefrologia", tags: ["acidose", "drc", "tratamento"] },
  { id: "fc-gen-nefrologia-007", front: "Em qual situação clínica a biópsia renal é fundamental para o diagnóstico de nefropatia glomerular?", back: "• Síndrome nefrítica aguda ou rapidamente progressiva.\n• Proteinúria nefrótica sem causa sistêmica evidente, especialmente em adultos.\n• IRA sem causa aparente ou que não responde ao tratamento inicial.\n• Suspeita de doença sistêmica com envolvimento renal (ex: lúpus, vasculites).", category: "nefrologia", tags: ["biópsia", "glomerulonefrite", "diagnóstico"] },
  { id: "fc-gen-nefrologia-008", front: "Quais as principais recomendações nutricionais para pacientes em hemodiálise?", back: "• Restrição de sódio (<2g/dia) e líquidos.\n• Restrição de potássio (<2-3g/dia) e fósforo (800-1000 mg/dia).\n• Ingestão proteica elevada (1.0-1.2 g/kg/dia de proteínas de alto valor biológico).\n• Suplementação de vitaminas hidrossolúveis (B e C) devido à perda durante a diálise.", category: "nefrologia", tags: ["hemodiálise", "nutrição", "dieta"] },
  { id: "fc-gen-nefrologia-009", front: "Qual a diferença principal entre cistite e pielonefrite em termos de apresentação clínica e manejo?", back: "Cistite: infecção do trato urinário baixo. Sintomas limitados a disúria, polaciúria, urgência e dor suprapúbica. Febre geralmente ausente.\n\nPielonefrite: infecção do trato urinário alto (rins). Sintomas incluem febre, calafrios, dor lombar (punho-percussão positiva), náuseas, vômitos. Requer antibióticos de maior espectro e duração (oral ou IV, a depender da gravidade). \nManejo: Ciprofloxacino ou CEFTA para pielonefrite; Nitrofurantoína ou Fosfomicina para cistite (não complicadas).", category: "nefrologia", tags: ["cistite", "pielonefrite", "itu"] },
  { id: "fc-gen-nefrologia-010", front: "Quais os critérios para início de terapia de substituição renal (TSR) na IRA?", back: "As indicações são geralmente mnemônicos 'AEIOU':\n• A - Acidose metabólica refratária (pH <7.1).\n• E - Eletrólitos (hipercalemia refratária, >6.5 mEq/L).\n• I - Intoxicações exógenas (drogas dialisáveis).\n• O - Overload (sobrecarga volêmica grave com edema pulmonar).\n• U - Uremia (encefalopatia urêmica, pericardite urêmica, sangramento urêmico).", category: "nefrologia", tags: ["ira", "tsr", "indicações"] },
  { id: "fc-gen-nefrologia-011", front: "Em que contexto é recomendado o uso de antagonistas do receptor mineralocorticoide (ARM) em DRC?", back: "• Pacientes com DRC (TFG >20 mL/min/1.73m²) e albuminúria persistente (ACR >30 mg/g) apesar de IECA/BRA.\n• Reduzir a progressão da DRC e eventos cardiovasculares.\n• Monitorar potássio e função renal de perto, pelo risco de hipercalemia e IRA. Exemplos: finerenona, espironolactona, eplerenona.", category: "nefrologia", tags: ["drc", "arm", "tratamento"] },
  { id: "fc-gen-nefrologia-012", front: "Qual o achado urinário mais sugestivo de glomerulonefrite?", back: "• Hematúria dismórfica (hemácias com alteração morfológica, indicando passagem por glomérulos danificados).\n• Cilindros hemáticos (agregados de hemácias dentro de uma matriz proteica, formados nos túbulos renais).\n• Proteinúria significativa.", category: "nefrologia", tags: ["glomerulonefrite", "urinálise", "diagnóstico"] },
  { id: "fc-gen-nefrologia-013", front: "Qual a principal etiologia de Doença Renal Crônica no Brasil?", back: "• Diabetes Mellitus (DM) é a principal causa, seguido de Hipertensão Arterial Sistêmica (HAS).\n• Juntos, DM e HAS são responsáveis por aproximadamente 70% dos casos de DRC no Brasil.", category: "nefrologia", tags: ["drc", "etiologia", "epidemiologia"] },
  { id: "fc-gen-nefrologia-014", front: "Quando se deve restringir a ingestão de fósforo na DRC?", back: "• A restrição de fósforo deve ser considerada a partir do estágio 3 da DRC (TFG <60 mL/min/1.73m²) se houver elevação do fósforo sérico ou PTH.\n• O objetivo é manter o fósforo sérico dentro da faixa normal (2.5-4.5 mg/dL), ou pelo menos <5.5 mg/dL para evitar calcificações vasculares e doença óssea.", category: "nefrologia", tags: ["drc", "fósforo", "dieta"] },
  { id: "fc-gen-nefrologia-015", front: "Quais as principais contraindicações absolutas para transplante renal?", back: "• Neoplasia maligna não controlada ou com expectativa de vida limitada.\n• Infecção ativa grave não tratável.\n• Doença cardíaca, pulmonar ou hepática grave e irreversível que limite drasticamente a expectativa de vida ou impeça manejo da imunossupressão.\n• Doença psiquiátrica grave não controlada ou drogadição ativa que impeça adesão ao tratamento.\n• Não adesão documentada a tratamento médico prévio.", category: "nefrologia", tags: ["transplante", "contraindicações", "cirurgia"] },
  { id: "fc-gen-infectologia-036", front: "Qual o critério diagnóstico para HIV primário, fora da janela imunológica?", back: "O diagnóstico de fase aguda ou primária de HIV é feito pela detecção de:\n- RNA viral (carga viral), em viremia alta, em conjunto com\n- Elisa de 4ª geração (antígeno p24 e/ou anticorpos HIV1/2) positivo, ou\n- Western Blot positivo.\nÉ importante excluir outras causas de soroconversão e considerar o contexto clínico.", category: "infectologia", tags: ["hiv", "diagnóstico"] },
  { id: "fc-gen-infectologia-037", front: "Quais os principais agentes etiológicos da meningite bacteriana em neonatos (0-28 dias)?", back: "Os principais agentes etiológicos da meningite bacteriana em neonatos são:\n- Streptococcus agalactiae (GBS)\n- Escherichia coli\n- Listeria monocytogenes\nA abordagem empírica deve cobrir esses patógenos.", category: "infectologia", tags: ["meningite", "neonatos"] },
  { id: "fc-gen-infectologia-038", front: "Qual a dose de oseltamivir para tratamento de influenza em adultos com comorbidades?", back: "A dose recomendada de oseltamivir para tratamento de influenza em adultos com comorbidades ou formas graves é de 75 mg via oral, duas vezes ao dia, por 5 dias. Em casos de influenza grave ou complicada, pode-se considerar a extensão do tratamento ou doses maiores (150 mg 2x/dia) a critério médico.", category: "infectologia", tags: ["influenza", "antiviral"] },
  { id: "fc-gen-infectologia-039", front: "Quais são os critérios de internação para pneumonia adquirida na comunidade (PAC) em adultos, segundo o escore CURB-65?", back: "Critérios de internação pelo escore CURB-65:\n- C = Confusão mental (desorientação no tempo/espaço)\n- U = Ureia > 50 mg/dL ou > 7 mmol/L\n- R = Frequência Respiratória ≥ 30 ipm\n- B = Pressão Arterial (PAS < 90 mmHg ou PAD ≤ 60 mmHg)\n- 65 = Idade ≥ 65 anos\nPontuação ≥ 2 indica internação hospitalar; ≥ 3 sugere UTI.", category: "infectologia", tags: ["pac", "internação", "curb-65"] },
  { id: "fc-gen-infectologia-040", front: "Qual a conduta inicial ambulatorial para sífilis primária em paciente não gestante, sem HIV?", back: "A conduta inicial ambulatorial para sífilis primária em paciente não gestante, sem HIV, é:\n- Penicilina G benzatina 2.400.000 UI, dose única, intramuscular. \nPara alérgicos à penicilina, a doxiciclina 100 mg, via oral, de 12 em 12 horas por 14 dias pode ser uma alternativa, mas a dessensibilização é preferível se possível.", category: "infectologia", tags: ["sífilis", "tratamento"] },
  { id: "fc-gen-infectologia-041", front: "Quais são as indicações de profilaxia pós-exposição (PEP) para raiva?", back: "As indicações de PEP para raiva incluem:\n- Exposições de risco elevado (mordeduras ou arranhaduras profundas, lambedura em pele não íntegra, contato de saliva com mucosas) por animais não vacinados, selvagens, ou cujo estado de vacinação é desconhecido.\n- Exposições por morcegos (mesmo sem lesão aparente).\n- Contato com animais de risco (cães/gatos) com comportamento atípico.\nA imunoglobulina e a vacina são administradas dependendo do tipo da exposição.", category: "infectologia", tags: ["raiva", "profilaxia"] },
  { id: "fc-gen-infectologia-042", front: "Qual o esquema vacinal primário para hepatite B em adultos não vacinados e não expostos previamente?", back: "O esquema vacinal primário para hepatite B em adultos não vacinados é de 3 doses:\n- 1ª dose: na data escolhida\n- 2ª dose: 1 mês após a 1ª dose\n- 3ª dose: 6 meses após a 1ª dose\nPara imunocomprometidos ou em situações especiais, pode ser necessário um esquema com 4 doses ou dose dobrada.", category: "infectologia", tags: ["hepatite b", "vacina"] },
  { id: "fc-gen-infectologia-043", front: "Quais os principais agentes do abscesso hepático piogênico?", back: "Os principais agentes etiológicos do abscesso hepático piogênico são:\n- K. pneumoniae (especialmente em países asiáticos, mas crescente globalmente)\n- E. coli\n- Streptococcus spp.\n- Enterococcus spp.\nPacientes com doenças do trato biliar ou em imunossupressão são mais suscetíveis.", category: "infectologia", tags: ["abscesso hepático", "etiologia"] },
  { id: "fc-gen-infectologia-044", front: "Qual a principal causa infecciosa de esofagite em pacientes com HIV?", back: "A principal causa infecciosa de esofagite em pacientes com HIV, especialmente aqueles com contagem de CD4 inferior a 100-200 células/mm³, é a Candida albicans. Outras causas incluem citomegalovírus (CMV) e herpes simplex vírus (HSV).", category: "infectologia", tags: ["esofagite", "hiv", "candida"] },
  { id: "fc-gen-infectologia-045", front: "Qual a dose de metronidazol para tratamento de colite pseudomembranosa leve a moderada?", back: "A dose de metronidazol para tratamento de colite pseudomembranosa leve a moderada, causada por Clostridioides difficile, é de 500 mg por via oral, três vezes ao dia, por 10 a 14 dias. Em casos mais graves ou refratários, o uso de vancomicina oral é preferível.", category: "infectologia", tags: ["clostridioides difficile", "tratamento"] },
  { id: "fc-gen-infectologia-046", front: "Quais são os critérios diagnósticos para infecção latente por tuberculose (ILTB) em adultos?", back: "Os critérios diagnósticos para ILTB em adultos incluem:\n- Teste cutâneo de tuberculina (PPD) positivo (induração ≥ 5mm ou ≥ 10mm, dependendo do grupo de risco) E/OU\n- Teste de liberação de interferon-gama (IGRA) positivo\n- Ausência de sintomas compatíveis com tuberculose ativa\n- Radiografia de tórax normal ou com alterações sugestivas de infecção prévia, mas sem evidências de doença ativa.\nÉ fundamental excluir TB ativa antes de iniciar o tratamento para ILTB.", category: "infectologia", tags: ["tuberculose", "iltb", "diagnóstico"] },
  { id: "fc-gen-infectologia-047", front: "Qual a conduta para infecção urinária baixa (cistite) em mulher grávida?", back: "A conduta para cistite em mulher grávida é:\n- Sempre tratar, mesmo que assintomática (bacteriúria assintomática também deve ser tratada).\n- Antibióticos seguros na gestação: cefalexina 500 mg 6/6h por 7 dias, ou nitrofurantoína 100mg 12/12h por 7 dias (evitar no 1º trimestre e próximo ao termo), ou fosfomicina 3g dose única.\n- Reavaliar e fazer urocultura de controle após o tratamento.", category: "infectologia", tags: ["itu", "gestação", "tratamento"] },
  { id: "fc-gen-infectologia-048", front: "Qual o principal mecanismo de ação dos aminoglicosídeos?", back: "Os aminoglicosídeos atuam inibindo a síntese proteica bacteriana. Eles se ligam irreversivelmente à subunidade 30S dos ribossomos bacterianos, o que distorce o sítio A e impede a leitura correta do mRNA, resultando na produção de proteínas anormais e não funcionais, levando à morte celular bacteriana. São bactericidas.", category: "infectologia", tags: ["aminoglicosídeos", "mecanismo de ação"] },
  { id: "fc-gen-infectologia-049", front: "Qual a dose de praziquantel para tratamento de esquistossomose mansoni?", back: "A dose de praziquantel para tratamento da esquistossomose mansoni em adultos é de 60 mg/kg de peso, via oral, em dose única. Para crianças, a dose pode variar ou ser fracionada em duas tomadas com intervalo de 4 a 6 horas. É essencial para a saúde pública em áreas endêmicas.", category: "infectologia", tags: ["esquistossomose", "tratamento"] },
  { id: "fc-gen-infectologia-050", front: "Quais os principais fatores de risco para fasciíte necrosante?", back: "Os principais fatores de risco para fasciíte necrosante incluem:\n- Diabetes mellitus\n- Imunossupressão (HIV, quimioterapia, uso de corticosteroides)\n- Trauma ou cirurgia recentes\n- Abuso de drogas intravenosas\n- Doença vascular periférica\n- Alcoolismo e DPOC", category: "infectologia", tags: ["fasciíte necrosante", "fatores de risco"] },
  { id: "fc-gen-infectologia-051", front: "Qual a indicação de uso de aciclovir no tratamento de varicela em criança imunocompetente?", back: "O aciclovir é geralmente indicado para varicela em crianças imunocompetentes com alto risco de complicações. Isso inclui:\n- Adolescentes (>12 anos)\n- Doença cutânea ou pulmonar crônica\n- Uso de salicilatos (risco de síndrome de Reye)\n- Doença grave (numerosas lesões, febre alta)\nDeve ser iniciado nas primeiras 24 horas do rash. Para a maioria das crianças saudáveis, o tratamento é sintomático.", category: "infectologia", tags: ["varicela", "aciclovir", "pediatria"] },
  { id: "fc-gen-infectologia-052", front: "Qual a etiologia mais comum da endocardite infecciosa em usuários de drogas intravenosas (UDIV)?", back: "A etiologia mais comum da endocardite infecciosa em usuários de drogas intravenosas (UDIV) é o Staphylococcus aureus. A infecção normalmente atinge a valva tricúspide. Outros agentes incluem Streptococcus spp. e Enterococcus spp., mas S. aureus é predominante devido à colonização da pele e via de administração.", category: "infectologia", tags: ["endocardite", "udiv", "staphylococcus aureus"] },
  { id: "fc-gen-infectologia-053", front: "Quais são as recomendações para antibioticoprofilaxia em cirurgias limpas contaminadas?", back: "Em cirurgias limpas contaminadas, onde há abertura de vísceras com colonização bacteriana normal (ex: cirurgia colorretal, apendicectomia com perfuração), a profilaxia antibiótica é altamente recomendada. Escolha do agente:\n- Cefazolina (para cobrir gram-positivos)\n- Associada a metronidazol (para anaeróbios)\n- Ou cefoxitina/cefotetana (que cobrem ambos)\nA dose deve ser administrada 30-60 minutos antes da incisão e, geralmente, não se estende por mais de 24 horas no pós-operatório.", category: "infectologia", tags: ["antibioticoprofilaxia", "cirurgia"] },
  { id: "fc-gen-infectologia-054", front: "Qual o tratamento empírico para abscesso cerebral em pacientes sem histórico de neurocirurgia ou trauma penetrante?", back: "O tratamento empírico para abscesso cerebral, na ausência de neurocirurgia ou trauma, deve ter cobertura ampla, incluindo:\n- Cefalosporina de 3ª geração (ex: Ceftriaxona 2g IV 12/12h) para aeróbios Gram-positivos e Gram-negativos\n- Metronidazol (500mg IV 8/8h) para anaeróbios\n- Vancomicina (15-20 mg/kg IV 8/8h ou 12/12h) se houver suspeita de Staphylococcus aureus resistente ou em casos pós-cirúrgicos.\nÉ crucial associar a drenagem cirúrgica, se indicada.", category: "infectologia", tags: ["abscesso cerebral", "tratamento empírico"] },
  { id: "fc-gen-infectologia-055", front: "Qual a principal complicação da febre amarela e sua manifestação clínica?", back: "A principal complicação da febre amarela é a doença viscerotrópica, caracterizada por:\n- Icterícia (daí o nome 'amarela')\n- Hemorragias (gengivorragia, epistaxe, melena, hematêmese - vômitos 'borra de café')\n- Comprometimento hepático severo (elevação de transaminases, coagulopatia)\n- Disfunção renal aguda.\nÉ uma doença grave com alta letalidade.", category: "infectologia", tags: ["febre amarela", "complicação"] },
  { id: "fc-gen-infectologia-056", front: "Qual o esquema de tratamento para toxoplasmose cerebral em pacientes com HIV?", back: "O esquema de tratamento para toxoplasmose cerebral em pacientes com HIV é:\n- Terapia combinada de sulfadiazina e pirimetamina.\n- Pirimetamina: 200 mg dose de ataque, seguido de 50-75 mg/dia.\n- Sulfadiazina: 1000-1500 mg, 4 vezes ao dia.\n- Adicionar ácido folínico (10-25 mg/dia) para prevenir supressão medular pela pirimetamina.\nA duração é de 6 semanas ou até resolução das lesões na imagem. Após, segue-se com terapia de manutenção.", category: "infectologia", tags: ["toxoplasmose", "hiv", "tratamento"] },
  { id: "fc-gen-infectologia-057", front: "Qual o antibiótico de primeira linha para escabiose em pacientes com intolerância ou contraindicação ao uso tópico?", back: "Para escabiose com intolerância ou contraindicação ao tratamento tópico (ex: crotamiton, permetrina), o tratamento oral de primeira linha é a ivermectina. A dose é de 200 µg/kg em dose única, repetida após 7-14 dias para cobrir o ciclo de vida do parasita. É contraindicada em gestantes, lactantes e crianças <15 kg.", category: "infectologia", tags: ["escabiose", "tratamento"] },
  { id: "fc-gen-infectologia-058", front: "Quais os critérios para diagnóstico de dengue grave?", back: "Os critérios para diagnóstico de dengue grave incluem:\n- Extravasamento plasmático grave (choque, acúmulo de líquidos com insuficiência respiratória)\n- Sangramento grave (hematêmese, melena, sangramento SNC)\n- Comprometimento grave de órgãos (insuficiência hepática, miocardite, encefalopatia)\n- Elevação progressiva do hematócrito e plaquetopenia grave são sinais de alerta.", category: "infectologia", tags: ["dengue", "dengue grave"] },
  { id: "fc-gen-infectologia-059", front: "Qual a profilaxia para candidíase esofágica em pacientes com HIV?", back: "A profilaxia primária para candidíase esofágica em pacientes com HIV não é rotineiramente recomendada. O tratamento é geralmente iniciado apenas quando há sintomas. No entanto, em pacientes com HIV avançado (CD4 < 100-200 células/mm³) e histórico de candidíase de repetição, pode-se considerar fluconazol semanal. O mais importante é a adesão à terapia antirretroviral (TARV) para recuperação imunológica.", category: "infectologia", tags: ["candidíase", "profilaxia", "hiv"] },
  { id: "fc-gen-infectologia-060", front: "Qual a principal causa infecciosa de perda de visão irremediável em pacientes com AIDS?", back: "A principal causa infecciosa de perda de visão irremediável em pacientes com AIDS, especialmente aqueles com contagem de CD4 muito baixa (< 50 células/mm³), é a retinite por citomegalovírus (CMV). Esta condição pode levar ao descolamento de retina e cegueira se não tratada precocemente. O tratamento envolve ganciclovir, valganciclovir ou foscarnete.", category: "infectologia", tags: ["aids", "perda de visão", "cmv"] },
  { id: "fc-gen-neurologia-006", front: "Quais os critérios diagnósticos clássicos para Esclerose Múltipla pela Classificação de McDonald (2017)?", back: "Os critérios de McDonald (2017) exigem evidências de disseminação no espaço (DSE) e no tempo (DST).\n- DSE: ≥1 lesão T2 em ≥2 das 4 localizações típicas (periventricular, justacortical, infratentorial, medular espinhal)\n- DST: Lesões novas em T2/Gadolinio em RM de seguimento, OU presença simultânea de lesões com e sem contraste em imagem única, OU evidência de atividade clínica em 2º surto\n- OU: 2 surtos e ≥2 lesões, com ou sem DSE/DST, se médico considerar forte evidência.\n- Sinais clínicos podem substituir critérios de imagem em casos específicos.", category: "neurologia", tags: ["esclerose múltipla", "critérios", "diagnóstico", "mcdonald"] },
  { id: "fc-gen-neurologia-007", front: "Qual a conduta inicial para um paciente com suspeita de AVC isquêmico em janela, com NIHSS entre 6 e 18, sem contraindicações para trombólise?", back: "A conduta inicial é trombólise intravenosa com alteplase.\n- Dose: 0,9 mg/kg (dose máxima 90 mg)\n- Administração: 10% da dose total em bolus IV em 1 minuto, seguido pelo restante Infusão contínua em 60 minutos.\n- Tempo: Idealmente nas primeiras 4,5 horas do início dos sintomas.\n- Monitoramento rigoroso da PA e sinais neurológicos.", category: "neurologia", tags: ["avc isquêmico", "trombólise", "alteplase", "emergência"] },
  { id: "fc-gen-neurologia-008", front: "Quais os principais fatores de risco modificáveis para o desenvolvimento de AVC?", back: "Os principais fatores de risco modificáveis para AVC são:\n- Hipertensão arterial sistêmica (HAS)\n- Diabetes Mellitus (DM)\n- Dislipidemia\n- Fibrilação Atrial (FA)\n- Tabagismo\n- Etilismo\n- Obesidade/Sedentarismo\n- Estenose carotídea sintomática", category: "neurologia", tags: ["avc", "fatores de risco", "prevenção"] },
  { id: "fc-gen-neurologia-009", front: "Como é classificada a hemorragia intraparenquimatosa (HIP) espontânea de acordo com a localização?", back: "A hemorragia intraparenquimatosa (HIP) espontânea é classicamente classificada pela localização em:\n- Lobar (cortical/subcortical): Associada a angiopatia amiloide, malformações ou drogas.\n- Profunda (ganglios da base, tálamo, tronco encefálico, cerebelo): Mais comumente associada à HAS crônica.\n- Ventricular: Pode ser primária ou secundária à extensão de HIP adjacente.", category: "neurologia", tags: ["hemorragia", "intraparenquimatosa", "avch"] },
  { id: "fc-gen-neurologia-010", front: "Quais os principais diagnósticos diferenciais de AVC isquêmico agudo?", back: "Os principais diagnósticos diferenciais de AVC isquêmico agudo incluem:\n- Crise epiléptica pós-ictal (paralisia de Todd)\n- Hipoglicemia/Hiperglicemia\n- Enxaqueca com aura (pode mimetizar)\n- Paralisia/Paresia de Bell\n- Tumor cerebral\n- Abcesso cerebral\n- Vertigem periférica (especialmente em AVC de tronco)\n- Conversão ou distúrbios psiquiátricos", category: "neurologia", tags: ["avc", "diagnóstico diferencial", "neurologia"] },
  { id: "fc-gen-neurologia-011", front: "Qual o manejo imediato de um paciente com crise epiléptica tônico-clônica generalizada em ambiente extra-hospitalar?", back: "O manejo imediato visa segurança e proteção:\n- Virar o paciente de lado (posição de recuperação) para evitar aspiração.\n- Afastar objetos perigosos.\n- Afrouxar roupas apertadas ao redor do pescoço.\n- Não tentar segurar ou conter os movimentos.\n- Não colocar objetos na boca.\n- Cronometrar a duração da crise. Chamar serviço de emergência se >5min ou outra crise sucessiva.", category: "neurologia", tags: ["crise epiléptica", "primeiros socorros", "emergência"] },
  { id: "fc-gen-neurologia-012", front: "Quais os critérios para o diagnóstico de Status Epiléptico (SE) pela ILAE (2015)?", back: "ILAE (2015) define Status Epiléptico como:\n- Crise epiléptica com duração de atividades convulsivantes >5 minutos.\n- OU duas ou mais crises clínicas não convulsivantes/convulsivantes sem retorno completo da consciência entre elas.\n- OU crise tônico-clônica contínua ou intermitente com duração >30 minutos (antiga definição).\nAmbas as definições são importantes no manejo clínico, priorizando a duração.", category: "neurologia", tags: ["status epiléptico", "crise epiléptica", "ilae"] },
  { id: "fc-gen-neurologia-013", front: "Qual a sequência de tratamento farmacológico para status epiléptico convulsivo refratário?", back: "O tratamento para status epiléptico convulsivo refratário (após falha de benzodiazepínicos e um fármaco de segunda linha) inclui:\n1. Benzodiazepínico IV (ex: lorazepam 0,1 mg/kg; diazepam 0,15-0,2 mg/kg).\n2. Fármaco de segunda linha (ex: fosfenitoína 15-20 mg FE/kg; levetiracetam 20-60 mg/kg; valproato de sódio 20-40 mg/kg).\n3. Se refratário: indução de coma com midazolam, propofol ou tiopental (infusão contínua com EEG de alvo de supressão de surtos).", category: "neurologia", tags: ["status epiléptico", "tratamento", "fármacos", "refratário"] },
  { id: "fc-gen-neurologia-014", front: "Quais os principais achados na ressonância magnética cerebral em pacientes com doença de Alzheimer em estágios iniciais?", back: "Em estágios iniciais da doença de Alzheimer, a RM cerebral pode mostrar:\n- Atrofia cortical discreta, predominantemente em lobos temporais mediais (hipocampo e córtex entorrinal).\n- Aumento dos sulcos corticais e alargamento dos ventrículos.\n- Volume normal ou levemente reduzido de substância branca. \n- Sem grandes alterações vasculares isquêmicas, a não ser que haja comorbidades.", category: "neurologia", tags: ["alzheimer", "rm", "atrofia", "demência"] },
  { id: "fc-gen-neurologia-015", front: "Descreva os achados clássicos do Líquor (LCR) em pacientes com Síndrome de Guillain-Barré (SGB).", back: "Os achados clássicos do LCR na SGB incluem:\n- Dissociação albumino-citológica: Aumento significativo da concentração de proteínas (>0,55 g/L ou 55 mg/dL), mas contagem celular (leucócitos) normal ou minimamente elevada (<10 células/mm³).\n- Pressão de abertura geralmente normal.\n- Glicose normal.\n- Este achado é geralmente mais evidente após a primeira semana de sintomas.", category: "neurologia", tags: ["guillain-barré", "lcr", "proteínas", "dissociação"] },
  { id: "fc-gen-neurologia-016", front: "Quais os principais fármacos utilizados no tratamento de primeira linha para crise de enxaqueca (abortivo)?", back: "Os fármacos de primeira linha para o tratamento abortivo da enxaqueca incluem:\n- AINEs (anti-inflamatórios não esteroides): Ibuprofeno, naproxeno, diclofenaco.\n- Triptanos: Sumatriptano, zolmitriptano, rizatriptano (agonistas seletivos dos receptores 5-HT1B/1D).\n- Medicações antieméticas (ex: metoclopramida) podem ser associadas para náuseas e como pró-cinéticos para absorção.\n- Paracetamol (acetaminofeno) para casos leves.", category: "neurologia", tags: ["enxaqueca", "tratamento", "abortivo", "triptanos"] },
  { id: "fc-gen-neurologia-017", front: "Quais os principais agentes etiológicos da meningite bacteriana aguda em adultos imunocompetentes no Brasil?", back: "Os principais agentes etiológicos da meningite bacteriana aguda em adultos imunocompetentes no Brasil são:\n- Streptococcus pneumoniae (pneumococo): Mais comum globalmente.\n- Neisseria meningitidis (meningococo): Causador de surtos e mais associado a exantema.\n- Haemophilus influenzae tipo b (Hib): Embora menos comum em adultos após vacinação infantil.\n- Listeria monocytogenes: Considerar em idosos, imunossuprimidos, gestantes.", category: "neurologia", tags: ["meningite", "bacteriana", "etiologia", "adultos"] },
  { id: "fc-gen-neurologia-018", front: "Qual a tríade clássica de Hakim-Adams na Hidrocefalia de Pressão Normal (HPN)?", back: "A tríade clássica de Hakim-Adams na Hidrocefalia de Pressão Normal (HPN) consiste em:\n1. Alterações da marcha: Apraxia da marcha, marcha magnética, passos curtos, instabilidade.\n2. Incontinência urinária: Urgência, polaciúria, incontinência de esforço.\n3. Demência: Bradipsiquismo, apatia, disfunção executiva, geralmente iniciando após os sintomas motores.", category: "neurologia", tags: ["hidrocefalia", "hpn", "hakim-adams", "demência"] },
  { id: "fc-gen-neurologia-019", front: "Qual o significado da presença de bandas oligoclonais no LCR em pacientes com Esclerose Múltipla?", back: "A presença de bandas oligoclonais (BOCs) no LCR é um achado importante na Esclerose Múltipla (EM).\n- Indicação: Síntese intratecal de imunoglobulinas (IgG) que não estão presentes no soro.\n- Significado: Evidência de inflamação crônica do SNC.\n- Relevância: Presente em >90% dos pacientes com EM clinicamente definida e é um critério de suporte ao diagnóstico pelos critérios de McDonald, especialmente se DSE/DST não forem completamente preenchidos.", category: "neurologia", tags: ["esclerose múltipla", "lcr", "bandas oligoclonais", "diagnóstico"] },
  { id: "fc-gen-neurologia-020", front: "Quais as indicações para anticoagulação em pacientes com fibrilação atrial (FA) e AVC isquêmico prévio?", back: "A anticoagulação está indicada na maioria dos pacientes com FA e AVC isquêmico prévio, salvo contraindicações absolutas.\n- Anticoagulantes orais diretos (DOACs/NOACs - apixabana, rivaroxabana, dabigatrana, edoxabana) são preferíveis à varfarina (antagonista da vitamina K).\n- Início: Geralmente após 4-14 dias do AVC, dependendo da extensão do infarto e risco de transformação hemorrágica (regra dos 1-3-6-12 dias para TIA, pequeno, moderado, grande infarto, respectivamente).\n- Avaliar risco-benefício individualmente (HAS-BLED vs CHA2DS2-VASc).", category: "neurologia", tags: ["fibrilação atrial", "avc isquêmico", "anticoagulação", "doacs"] },
  { id: "fc-gen-neurologia-021", front: "Qual o papel da punção lombar (PL) no diagnóstico de Hemorragia Subaracnoide (HSA) na ausência de achados na TC?", back: "A punção lombar (PL) é crucial para diagnosticar HSA quando a TC de crânio é normal ou inconclusiva, especialmente se os sintomas forem sugestivos e a TC for realizada >6 horas do início da cefaleia.\n- Achados: Xantocromia (cor amarelada do LCR devido à degradação da hemoglobina), presença de hemácias persistentes em amostras sequenciais.\n- Amostras seriadas (tubos 1, 2, 3) são importantes para diferenciar HSA de punção traumática (diminuição progressiva de hemácias).\n- A xantocromia é o achado mais confiável, surgindo após ~6-12h e durando 2-4 semanas.", category: "neurologia", tags: ["hemorragia subaracnoide", "hsa", "punção lombar", "lcr"] },
  { id: "fc-gen-neurologia-022", front: "Quais os principais sintomas da Miastenia Gravis, e como diferenciá-los de outras fraquezas musculares?", back: "Os principais sintomas da Miastenia Gravis (MG) são:\n- Fraqueza muscular flutuante e fatigável que piora com o esforço e melhora com o repouso.\n- Mais comum: Ptose palpebral, diplopia (fraqueza ocular).\n- Disfagia, disartria (fraqueza bulbar).\n- Fraqueza de membros (proximal > distal).\n- Diferenciação: A fatigabilidade e a flutuação são as chaves. Não há alterações de sensibilidade, reflexos tendíneos costumam ser normais (exceto se músculos fatigados) e não há atrofia precoce.", category: "neurologia", tags: ["miastenia gravis", "fraqueza", "sintomas", "neuromuscular"] },
  { id: "fc-gen-neurologia-023", front: "Qual a tríade clássica do acometimento por neuronopatia motora superior em doenças como Esclerose Lateral Amiotrófica (ELA)?", back: "A tríade clássica da neuronopatia motora superior (NMS) inclui:\n1. Hiperreflexia: Reflexos tendíneos profundos exaltados.\n2. Hipertonia/Espasticidade: Aumento do tônus muscular dependente da velocidade (sinal do canivete).\n3. Sinais de Babinski e/ou Hoffmann positivos: Respostas extensoras plantares e/ou flexão do polegar e indicador após estimulação.\nOutros achados podem incluir clonus e fraqueza muscular.", category: "neurologia", tags: ["ela", "neuropatia motora", "sinal de babinski", "esclerose lateral amiotrófica"] },
  { id: "fc-gen-neurologia-024", front: "Qual a conduta para um paciente com tremor essencial que afeta significativamente a sua qualidade de vida?", back: "A conduta para o tremor essencial (TE) sintomático, que afeta a qualidade de vida, é:\n- Primeira linha: Propranolol (beta-bloqueador) ou Primidona (anticonvulsivante).\n- Iniciar com doses baixas e titular lentamente.\n- Pode-se tentar associações se monoterapia inadequada.\n- Segunda linha (se refratário): Topiramato, Gabapentina, Alprazolam.\n- Casos graves refratários: Estimulação cerebral profunda (DBS) ou ultrassom focal guiado por RM (HIFU) podem ser considerados.", category: "neurologia", tags: ["tremor essencial", "tratamento", "propranolol", "primidona"] },
  { id: "fc-gen-neurologia-025", front: "Cite os principais efeitos adversos da levodopa na Doença de Parkinson.", back: "Os principais efeitos adversos da levodopa na Doença de Parkinson incluem:\n- Efeitos precoces (agudos): Náuseas, vômitos, hipotensão ortostática, tontura.\n- Efeitos tardios (crônicos, após uso prolongado): Discinesias (movimentos involuntários irregulares), fenômeno 'on-off' (flutuações motoras), distonias, distúrbios do sono, alucinações e psicose em fases avançadas.", category: "neurologia", tags: ["doença de parkinson", "levodopa", "efeitos adversos"] },
  { id: "fc-gen-neurologia-026", front: "Quais os principais fatores de mau prognóstico em pacientes com estado de mal epiléptico?", back: "Os principais fatores de mau prognóstico em estado de mal epiléptico (EME) incluem:\n- Etiologia: Causas estruturais agudas (AVC, infecção, trauma) ou anóxia cerebral têm pior prognóstico.\n- Duração do EME: Quanto maior a duração, pior o prognóstico.\n- Idade avançada.\n- Presença de EME não convulsivo ou 'subtle' (subclinical).\n- Falha em responder rapidamente à terapia inicial.\n- Pontuação baixa na escala de coma de Glasgow no início.", category: "neurologia", tags: ["status epiléptico", "prognóstico", "etiologia"] },
  { id: "fc-gen-neurologia-027", front: "Quais os principais agentes que causam a Síndrome de Encefalopatia Posterior Reversível (PRES)?", back: "A Síndrome de Encefalopatia Posterior Reversível (PRES) está associada a vários agentes e condições:\n- Hipertensão arterial grave e de rápida instalação (principal causa).\n- Agentes imunossupressores/quimioterápicos (ex: ciclosporina, tacrolimus, bevacizumab).\n- Doenças autoimunes (ex: lúpus eritematoso sistêmico).\n- Eclampsia/Pré-eclampsia.\n- Sepse, choque, insuficiência renal.\n- Disfunção endotelial subjacente.", category: "neurologia", tags: ["pres", "hipertensão", "encefalopatia", "reversível"] },
  { id: "fc-gen-neurologia-028", front: "Quais as características do LCR que sugerem infecção viral (meningite ou encefalite viral)?", back: "O LCR em infecções virais (meningite ou encefalite) classicamente apresenta:\n- Pleocitose linfocítica: Aumento de células, predominantemente linfócitos (geralmente <1.000 células/mm³).\n- Proteínas: Normais ou discretamente elevadas.\n- Glicose: Normal (a menos que o vírus afete a barreira hematoencefálica ou haja inflamação intensa).\n- Pressão de abertura: Normal ou levemente elevada.\n- Pesquisa de patógenos por PCR (padrão-ouro para identificação viral específica).", category: "neurologia", tags: ["lcr", "meningite viral", "encefalite", "diagnóstico"] },
  { id: "fc-gen-neurologia-029", front: "Qual a principal complicação aguda da espondilose cervical com mielopatia?", back: "A principal complicação aguda da espondilose cervical com mielopatia é o trauma.\n- Qualquer trauma cervical, mesmo que de baixa energia, pode agudizar a compressão medular crônica.\n- Isso pode levar a um piora neurológica súbita e grave, com aumento da fraqueza, perda sensorial e disfunção esfincteriana.\n- Pacientes com mielopatia cervical pré-existente têm maior risco de lesão medular aguda pós-traumática.", category: "neurologia", tags: ["espondilose cervical", "mielopatia", "complicação", "trauma"] },
  { id: "fc-gen-neurologia-030", front: "Quais os critérios modificados de Framingham para diagnóstico de Acidente Isquêmico Transitório (AIT) em serviços de emergência brasileiros?", back: "Para o diagnóstico de AIT, em serviços brasileiros, usamos a definição clínica:\n- Deficiência neurológica focal (ou retiniana) de início súbito atribuível à isquemia, com duração inferior a 24 horas.\n- Mais importante, hoje o diagnóstico considera a ausência de infarto agudo na imagem cerebral (RM com DWI).\n- A classificação de Framingham moderna não é mais usada para 'AIT' per se, mas os clínicos ainda avaliam a 'transitoriedade' dos sintomas.\n- O foco mudou para considerar qualquer sintoma isquêmico agudo como AVC até que a imagem exclua lesão irreversível.", category: "neurologia", tags: ["ait", "avc", "diagnóstico", "neurologia"] },
  { id: "fc-gen-nefrologia-016", front: "Quais os critérios diagnósticos para lesão renal aguda (LRA) KDIGO estágio 3?", back: "Os critérios diagnósticos para LRA KDIGO estágio 3 são:\n- Aumento da creatinina sérica para ≥3 vezes o valor basal.\n- Aumento da creatinina sérica para ≥4,0 mg/dL ou início de terapia renal substitutiva (TRS).\n- Débito urinário <0,3 mL/kg/h por ≥24 horas ou anúria por ≥12 horas.", category: "nefrologia", tags: ["lra", "kdigo", "diagnóstico"] },
  { id: "fc-gen-nefrologia-017", front: "Qual a principal causa de glomerulonefrite rapidamente progressiva (GNRP) tipo III (pauci-imune)?", back: "A principal causa de GNRP tipo III (pauci-imune) é a vasculite associada a ANCA (anticorpos anticitoplasma de neutrófilos).\n- Estas vasculites incluem a granulomatose com poliangiite (GPA), a poliangiite microscópica (PAM) e a granulomatose eosinofílica com poliangiite (EGPA).", category: "nefrologia", tags: ["gnrp", "vasculite", "anemia"] },
  { id: "fc-gen-nefrologia-018", front: "Qual a conduta inicial para hipercalemia grave (K+ >6,5 mEq/L ou alterações eletrocardiográficas)?", back: "A conduta inicial para hipercalemia grave envolve:\n1. Estabilização da membrana: Gluconato de cálcio 10% IV (10-20 mL em 5-10 min).\n2. Deslocamento de K+ para o intracelular: Insulina regular 10 UI + Glicose 50% 50 mL IV OU salbutamol nebulizado.\n3. Remoção de K+ do corpo: Furosemida IV OU resinas trocadoras de íons (via oral/retal). Hemodiálise em casos refratários.", category: "nefrologia", tags: ["hipercalemia", "emergência", "distúrbio-eletrolítico"] },
  { id: "fc-gen-nefrologia-019", front: "Quais as indicações para o início de terapia renal substitutiva (TRS) em LRA?", back: "As indicações para o início de TRS em LRA são mnemônicos 'AEIOU':\n- A: Acidose metabólica refratária (pH <7,1).\n- E: Eletrólitos (hipercalemia grave, hipercalcemia).\n- I: Intoxicações exógenas dialisáveis.\n- O: Overload (sobrecarga hídrica refratária com edema pulmonar).\n- U: Uremia grave (encefalopatia, pericardite urêmica, sangramento inexplicável).", category: "nefrologia", tags: ["lra", "trs", "nefrologia"] },
  { id: "fc-gen-nefrologia-020", front: "Qual a principal alteração hidro-eletrolítica encontrada na síndrome de lise tumoral?", back: "A síndrome de lise tumoral se caracteriza por:\n- Hipercalemia (liberação de K+ intracelular).\n- Hiperfosfatemia (liberação de fosfato intracelular).\n- Hiperuricemia (liberação de purinas, que são metabolizadas a ácido úrico).\n- Hipocalcemia (devido à ligação do cálcio com o fosfato liberado, formando cristais).", category: "nefrologia", tags: ["lise-tumoral", "oncologia", "eletrólitos"] },
  { id: "fc-gen-nefrologia-021", front: "Descreva o mecanismo de ação dos inibidores do SGLT2 (iSGLT2) e seus principais benefícios renais.", back: "Os iSGLT2 (ex: dapagliflozina, empagliflozina) inibem o cotransportador de sódio-glicose tipo 2 nos túbulos contorcidos proximais, reduzindo a reabsorção de glicose e sódio filtrados, levando à glicosúria e natriurese. Os benefícios renais incluem:\n- Redução da proteinúria.\n- Diminuição da pressão intraglomerular.\n- Retardo da progressão da doença renal crônica.\n- Redução de eventos cardiovasculares e desfechos renais adversos em pacientes com DRC e/ou DM2.", category: "nefrologia", tags: ["isglt2", "drc", "farmacologia"] },
  { id: "fc-gen-nefrologia-022", front: "Qual a apresentação clínica clássica da síndrome nefrítica aguda?", back: "A síndrome nefrítica aguda se apresenta tipicamente com:\n- Hematúria (macroscópica ou microscópica), frequentemente com dismorfismo eritrocitário e cilindros hemáticos.\n- Edema (geralmente periorbitário ou periférico, devido à retenção de sódio e água).\n- Hipertensão arterial (devido à expansão de volume e ativação do SRAA).\n- Oligúria.\n- Proteinúria subnefrótica (<3,5 g/dia).", category: "nefrologia", tags: ["síndrome-nefrítica", "glomerulonefrite", "apresentação"] },
  { id: "fc-gen-nefrologia-023", front: "Cite as principais complicações da doença renal crônica (DRC) e as medidas de manejo para 'doença óssea e mineral'.", back: "As principais complicações da DRC incluem anemia, doença óssea e mineral, acidose metabólica, hipercalemia, e doença cardiovascular. Para a doença óssea e mineral:\n- Controle de fósforo sérico: dieta restrita em fósforo, quelantes de fósforo (carbonato de cálcio, sevelamer).\n- Vitamina D: reposição para 25(OH)D >30 ng/mL.\n- Calcitriol ou análogos: para hipocalcemia ou PTH elevado persistente.\n- Calcimiméticos (cinacalcete): para hiperparatireoidismo secundário grave.", category: "nefrologia", tags: ["drc", "complicações", "osso"] },
  { id: "fc-gen-nefrologia-024", front: "Qual a dose de heparina não fracionada (HNF) e o tempo alvo de TTPa em uma embolia pulmonar massiva em paciente sem contraindicações?", back: "Para embolia pulmonar massiva, a dose de HNF é:\n- Bolus IV: 80 UI/kg.\n- Infusão contínua: 18 UI/kg/h.\n- O tempo alvo de TTPa (tempo de tromboplastina parcial ativada) deve ser de 1,5 a 2,5 vezes o valor de controle do laboratório ou dentro da faixa terapêutica específica (geralmente entre 60 e 80 segundos), monitorado a cada 4-6 horas inicialmente.", category: "nefrologia", tags: ["heparina", "tromboembolismo", "anticoagulação"] },
  { id: "fc-gen-nefrologia-025", front: "Quais são os principais fatores de risco para LRA nos pacientes hospitalizados?", back: "Os principais fatores de risco para LRA em pacientes hospitalizados incluem:\n- Condições pré-existentes: DRC, diabetes mellitus, hipertensão, idade avançada, insuficiência cardíaca.\n- Condições agudas: Sepse, hipovolemia, choque, grandes cirurgias, síndrome cardiorrenal.\n- Nefrotoxinas: Contraste iodado, AINEs, aminoglicosídeos, inibidores da ECA/BRA em certas situações.\n- Obstrução do trato urinário.", category: "nefrologia", tags: ["lra", "fatores-de-risco", "hospitalização"] },
  { id: "fc-gen-nefrologia-026", front: "Qual o quadro clínico da nefrite intersticial aguda induzida por drogas?", back: "A nefrite intersticial aguda induzida por drogas apresenta-se com a 'tríade clássica' em 10-20% dos casos:\n- Febre.\n- Rash cutâneo.\n- Eosinofilia/eosinofilúria.\nOutros achados comuns incluem: LRA, proteinúria mínima, hematúria, piúria estéril e, por vezes, dor lombar. Os AINEs e antibióticos (betalactâmicos, sulfas) são causas comuns.", category: "nefrologia", tags: ["nia", "drogas", "alergia"] },
  { id: "fc-gen-nefrologia-027", front: "Qual a principal indicação para uso de diuréticos de alça (furosemida) na DRC?", back: "A principal indicação para o uso de diuréticos de alça (como a furosemida) na DRC é o controle de sobrecarga hídrica e edema, especialmente quando há diminuição da taxa de filtração glomerular (TFG).\n- Eles atuam no ramo ascendente espesso da alça de Henle, aumentando a excreção de sódio, potássio, cálcio e magnésio, sendo eficazes mesmo com TFG reduzida.", category: "nefrologia", tags: ["drc", "diurético", "furosemida"] },
  { id: "fc-gen-nefrologia-028", front: "Descreva a diferença entre proteinúria seletiva e não seletiva na síndrome nefrótica.", back: "Na síndrome nefrótica:\n- Proteinúria seletiva: Predomínio de albumina na urina, com pouca excreção de proteínas de alto peso molecular (ex: IgG). Sugere lesão glomerular menos grave ou mais 'seletiva' no bloqueio de proteínas, como na Doença de Lesões Mínimas (DLM).\n- Proteinúria não seletiva: Excreção significativa de albumina e outras proteínas de alto peso molecular (ex: IgG). Indica lesão glomerular mais extensa e grave, como na glomeruloesclerose segmentar e focal (GESF) ou glomerulonefrite membranosa.", category: "nefrologia", tags: ["síndrome-nefrótica", "proteinúria", "glomerular"] },
  { id: "fc-gen-nefrologia-029", front: "Qual a principal causa infecciosa de glomerulonefrite pós-infecciosa e seu período de latência?", back: "A principal causa infecciosa de glomerulonefrite pós-infecciosa é a infecção por Streptococcus pyogenes (estreptococo beta-hemolítico do grupo A).\n- O período de latência é de aproximadamente 1-2 semanas após infecção de garganta (faringite) ou 3-6 semanas após infecção de pele (impetigo).", category: "nefrologia", tags: ["glomerulonefrite", "pós-infecciosa", "estreptococo"] },
  { id: "fc-gen-nefrologia-030", front: "Quais os principais exames a serem solicitados para investigação de hipertensão renovascular?", back: "Para investigação de hipertensão renovascular, os exames a serem solicitados incluem:\n- Ultrassonografia Doppler de artérias renais: Método de triagem inicial.\n- Angiotomografia (Angio-TC) ou Angiografia por Ressonância Magnética (Angio-RM): Gold standard não invasivo (Angio-RM é preferível em DRC devido ao contraste). \n- Arteriografia renal: Padrão-ouro invasivo, com potencial para intervenção (angioplastia/stent).", category: "nefrologia", tags: ["hipertensão-renovascular", "diagnóstico", "exames"] },
  { id: "fc-gen-nefrologia-031", front: "Qual o manejo da hiponatremia grave sintomática (Na+ <120 mEq/L ou manifestações neurológicas)?", back: "O manejo da hiponatremia grave sintomática requer correção lenta e cuidadosa para evitar a síndrome de desmielinização osmótica:\n- Para sintomas graves (convulsões, coma): Solução salina hipertônica 3% (100 mL IV em 10-20 min, repetindo se necessário), com objetivo de aumentar o Na em 4-6 mEq/L nas primeiras 6 horas.\n- Limite o aumento do Na para <8-10 mEq/L em 24h e <18 mEq/L em 48h.\n- Identificar e tratar a causa subjacente (ex: SIADH, hipovolemia).", category: "nefrologia", tags: ["hiponatremia", "emergência", "distúrbio-eletrolítico"] },
  { id: "fc-gen-nefrologia-032", front: "Quais as indicações para biópsia renal em um paciente com síndrome nefrótica?", back: "As indicações para biópsia renal em síndrome nefrótica variam:\n- Adultos: Quase sempre indicada, pois DLM é menos comum e outras causas exigem tratamento específico.\n- Crianças: Indicada se >10-12 anos, resistente a corticoides, ou com características atípicas (hipertensão grave, hematúria macroscópica, hipocomplementemia persistente, função renal alterada).\n- Excluir causas secundárias antes da biópsia.", category: "nefrologia", tags: ["biópsia-renal", "síndrome-nefrótica", "indicações"] },
  { id: "fc-gen-nefrologia-033", front: "Qual a principal causa de doença renal crônica no Brasil e como é feito o rastreamento?", back: "No Brasil, as duas principais causas de DRC são diabetes mellitus (DM) e hipertensão arterial sistêmica (HAS).\n- O rastreamento é realizado através de: \n    - Ureia e creatinina sérica para cálculo da TFG (eGFR).\n    - Exame de urina simples (urina tipo 1) para detecção de hematúria ou proteinúria.\n    - Relação albumina/creatinina urinária (RACu) para quantificação da albuminúria, especialmente em pacientes com DM e HAS.", category: "nefrologia", tags: ["drc", "epidemiologia", "rastreamento"] },
  { id: "fc-gen-nefrologia-034", front: "Quais as principais características da nefropatia por IgA?", back: "A nefropatia por IgA (doença de Berger) é a glomerulonefrite primária mais comum no mundo, caracterizada por:\n- Depósitos mesangiais de IgA na biópsia renal.\n- Clínica variada: hematúria macroscópica recorrente (especialmente após infecções de via aéreas superiores ou gastrointestinais), proteinúria (frequentemente subnefrótica), hipertensão, ou LRA.\n- Diagnóstico definitivo por biópsia renal com imunofluorescência.", category: "nefrologia", tags: ["nefropatia-iga", "glomerulonefrite", "diagnóstico"] },
  { id: "fc-gen-nefrologia-035", front: "Qual a principal causa de morte em pacientes em diálise?", back: "A principal causa de morte em pacientes em diálise (tanto hemodiálise quanto diálise peritoneal) é a doença cardiovascular.\n- Isso inclui eventos como infarto agudo do miocárdio, acidente vascular cerebral, insuficiência cardíaca e doença arterial periférica, exacerbados por fatores como hipertensão, dislipidemia, inflamação crônica, estresse oxidativo e calcificação vascular induzida pela uremia.", category: "nefrologia", tags: ["diálise", "mortalidade", "doença-cardiovascular"] },
  { id: "fc-gen-nefrologia-036", front: "Como diferenciar LRA pré-renal de necrose tubular aguda (NTA) através de parâmetros urinários?", back: "A diferenciação pode ser feita por:\n- LRA pré-renal:\n    - FeNa <1% (ou FeUréia <35%)\n    - Osmolaridade urinária >500 mOsm/kg\n    - Sódio urinário <20 mEq/L\n    - Densidade urinária >1.020\n- NTA estabelecida:\n    - FeNa >2% (ou FeUréia >50%)\n    - Osmolaridade urinária <350 mOsm/kg\n    - Sódio urinário >40 mEq/L\n    - Densidade urinária <1.010", category: "nefrologia", tags: ["lra", "nta", "diferencial"] },
  { id: "fc-gen-nefrologia-037", front: "Quais as orientações dietéticas gerais para pacientes com DRC em estágio 4-5 que não estão em diálise?", back: "As orientações dietéticas para DRC estágio 4-5 (não dialítica) visam retardar a progressão e manejar sintomas:\n- Restrição proteica: 0,6-0,8 g/kg/dia (qualidade de alta valor biológico).\n- Restrição de sódio: <2 g/dia.\n- Restrição de fósforo: <800-1000 mg/dia.\n- Restrição de potássio: individualizada, se hipercalemia (geralmente <2-3 g/dia).\n- Controle hídrico: conforme débito urinário e estado de volemia.", category: "nefrologia", tags: ["drc", "dieta", "nutrição"] },
  { id: "fc-gen-nefrologia-038", front: "Qual o principal mecanismo de dano renal induzido por contraste iodado?", back: "O principal mecanismo de dano renal induzido por contraste iodado é a vasoconstrição renal e isquemia medular, juntamente com o dano tubular direto.\n- O contraste causa liberação de endotelina e adenosina, levando à vasoconstrição. Além disso, pode gerar radicais livres e estresse oxidativo nas células tubulares, especialmente em pacientes com fatores de risco como DRC pré-existente, diabetes e hipovolemia.", category: "nefrologia", tags: ["contraste", "nefrotoxicidade", "lra"] },
  { id: "fc-gen-nefrologia-039", front: "Quais as contraindicações absolutas para transplante renal?", back: "As contraindicações absolutas para transplante renal incluem:\n- Neoplasia maligna ativa ou malignidade com alto risco de recorrência.\n- Infecção ativa não controlada (ex: HIV sem controle, tuberculose ativa).\n- Doença cardiovascular grave não tratável ou ativa que inviabilize o procedimento ou comprometa a sobrevida.\n- Doença psicossocial grave ou não adesão comprovada ao tratamento.\n- Dependência de álcool ou drogas não tratada.", category: "nefrologia", tags: ["transplante-renal", "contraindicações", "critérios"] },
  { id: "fc-gen-nefrologia-040", front: "Qual o tratamento primário para a Doença de Lesões Mínimas (DLM) em adultos?", back: "O tratamento primário para a Doença de Lesões Mínimas (DLM) em adultos é a corticoterapia.\n- Prednisona oral, geralmente em dose de 1 mg/kg/dia (máximo 60-80 mg/dia) por 8 a 16 semanas, seguido de desmame lento.\n- Para casos refratários ou recidivantes, podem ser usados ciclosporina, tacrolimus, micofenolato de mofetila ou rituximabe.", category: "nefrologia", tags: ["dlm", "síndrome-nefrótica", "tratamento"] },
  { id: "fc-gen-endocrinologia-001", front: "Quais os critérios diagnósticos para Diabetes Mellitus tipo 2 (DM2) segundo a Sociedade Brasileira de Diabetes (SBD)?", back: "- Glicemia de jejum ≥ 126 mg/dL (após 8h de jejum)\n- Glicemia casual ≥ 200 mg/dL COM sintomas clássicos (poliúria, polidipsia, perda ponderal inexplicável)\n- Glicemia 2h após TOTG ≥ 200 mg/dL (com 75g de glicose anidra)\n- HbA1c ≥ 6,5%", category: "endocrinologia", tags: ["diabetes", "diagnóstico", "sbd"] },
  { id: "fc-gen-endocrinologia-002", front: "Qual a conduta inicial para um nódulo tireoidiano com ultrassonografia classificada como TIRADS 5?", back: "- Indica punção aspirativa por agulha fina (PAAF) para avaliação citopatológica.\n- Tirads 5: alto risco de malignidade, com chance de malignidade >26%.", category: "endocrinologia", tags: ["tireoide", "nódulo", "tirads"] },
  { id: "fc-gen-endocrinologia-003", front: "Um paciente em uso de levotiroxina para hipotireoidismo apresenta TSH de 0,1 mUI/L e T4L normal. Qual a conduta?", back: "- O TSH está suprimido, indicando excesso de hormônio tireoidiano.\n- Reduzir a dose de levotiroxina em 12,5 a 25 mcg/dia e reavaliar TSH em 6-8 semanas.\n- Monitorar sintomas de hipertireoidismo (taquicardia, tremores).", category: "endocrinologia", tags: ["hipotireoidismo", "levotiroxina", "tsh"] },
  { id: "fc-gen-endocrinologia-004", front: "Quais os critérios diagnósticos para Síndrome de Cushing?", back: "- Para diagnóstico laboratorial: ao menos dois testes alterados.\n- Cortisol livre urinário de 24h elevado (2 a 3 vezes o limite superior da normalidade).\n- Cortisol salivar noturno elevado (coleta às 23h-24h).\n- Teste de supressão com dexametasona 1mg ( overnight ) com cortisol plasmático > 1,8 µg/dL às 8h.", category: "endocrinologia", tags: ["cushing", "diagnóstico", "cortisol"] },
  { id: "fc-gen-endocrinologia-005", front: "Qual a principal causa e o tratamento inicial da crise addisoniana?", back: "- Principal causa: suspensão abrupta de glicocorticoides em pacientes com insuficiência adrenal crônica ou estresse agudo.\n- Tratamento inicial: reposição volêmica com soro fisiológico 0,9% (2-3 litros na 1ª hora).\n- Glicocorticoide parenteral: hidrocortisona 100 mg IV em bolus, seguida de 200-300 mg/dia em infusão contínua ou 50-100 mg IV a cada 6-8h.", category: "endocrinologia", tags: ["addison", "crise adrenal", "hidrocortisona"] },
  { id: "fc-gen-endocrinologia-006", front: "Quais os valores de referência para o diagnóstico de osteoporose pela densitometria óssea?", back: "- Osteoporose: T-score ≤ -2,5 desvios-padrão em coluna lombar, fêmur ou colo femoral.\n- Osteopenia: T-score entre -1,0 e -2,5 desvios-padrão.\n- Normalidade: T-score ≥ -1,0 desvio-padrão.", category: "endocrinologia", tags: ["osteoporose", "densitometria", "t-score"] },
  { id: "fc-gen-endocrinologia-007", front: "Qual o mecanismo de ação da metformina e suas principais contraindicações?", back: "- Mecanismo: Reduz a produção hepática de glicose (gliconeogênese) e aumenta a sensibilidade à insulina nos tecidos periféricos.\n- Contraindicações: Insuficiência renal (TFGe < 30 mL/min/1,73m²), insuficiência cardíaca descompensada, acidose metabólica, doença hepática grave.", category: "endocrinologia", tags: ["metformina", "dm2", "farmacologia"] },
  { id: "fc-gen-endocrinologia-008", front: "Cite os 3 principais exames para o rastreamento de complicações microvasculares do Diabetes Mellitus.", back: "- Retinopatia diabética: exame oftalmológico com fundoscopia anual.\n- Nefropatia diabética: dosagem de albumina urinária (microalbuminúria) e creatinina sérica com cálculo da TFGe anual.\n- Neuropatia diabética: sensibilidade protetora com monofilamento de Semmes-Weinstein anualmente.", category: "endocrinologia", tags: ["diabetes", "complicações", "rastreamento"] },
  { id: "fc-gen-endocrinologia-009", front: "Qual o tratamento de escolha para o feocromocitoma antes da ressecção cirúrgica?", back: "- Bloqueio alfa-adrenérgico com fenoxibenzamina (não seletivo, de ação prolongada) ou prazosina/doxazosina (seletivos) por 10-14 dias.\n- Após controle da pressão arterial e taquicardia reflexa, iniciar betabloqueador (propranolol).", category: "endocrinologia", tags: ["feocromocitoma", "pré-operatório", "bloqueador"] },
  { id: "fc-gen-endocrinologia-010", front: "Quais os principais efeitos adversos da terapia com análogos de GLP-1 (ex: liraglutida, semaglutida)?", back: "- Gastrointestinais: Náuseas, vômitos, diarreia, constipação.\n- Pancreatite (rara).\n- Litíase biliar.\n- Nódulos tireoidianos (especialmente em roedores, relevância em humanos incerta).", category: "endocrinologia", tags: ["glp1", "dm2", "efeitos-adversos"] },
  { id: "fc-gen-endocrinologia-011", front: "Discorra sobre a conduta em tireotoxicose durante a gestação.", back: "- Doença de Graves é a causa mais comum.\n- Tratamento com tionamidas em dose mínima eficaz para manter T4L no limite superior da normalidade.\n- Preferir propiltiouracil no 1º trimestre (menor risco de teratogenicidade, exceto aplasia cutânea).\n- Mudar para metimazol no 2º e 3º trimestres (menor hepatotoxicidade).", category: "endocrinologia", tags: ["tireotoxicose", "gestação", "doença-graves"] },
  { id: "fc-gen-endocrinologia-012", front: "Quais as indicações para o rastreamento de Diabetes Mellitus em adultos assintomáticos?", back: "- Indivíduos com sobrepeso ou obesidade (IMC ≥ 25 kg/m² ou ≥ 23 kg/m² em asiáticos).\n- Com um ou mais fatores de risco adicionais: história familiar de DM, sedentarismo, hipertensão, dislipidemia (HDL < 35 mg/dL e/ou TG > 250 mg/dL), SOP, histórico de DMG.", category: "endocrinologia", tags: ["dm2", "rastreamento", "fatores-risco"] },
  { id: "fc-gen-endocrinologia-013", front: "Qual a principal causa de hiperparatireoidismo primário e seu tratamento definitivo?", back: "- Principal causa: adenoma de paratireoide (85-90% dos casos).\n- Tratamento definitivo: paratireoidectomia cirúrgica.", category: "endocrinologia", tags: ["paratireoide", "hiperparatireoidismo", "adenoma"] },
  { id: "fc-gen-endocrinologia-014", front: "Um paciente diabético tipo 2 apresenta albuminúria persistente (2 dosagens em 3-6 meses) entre 30-300 mg/24h ou 30-300 ug/mg creatinina. Qual a conduta terapêutica inicial, além do controle glicêmico?", back: "- Iniciar inibidor da enzima conversora de angiotensina (IECA) ou bloqueador do receptor de angiotensina II (BRA II).\n- Monitorizar creatinina e potássio sérico 1-2 semanas após início ou aumento da dose.\n- Controle rigoroso da pressão arterial (<130/80 mmHg).", category: "endocrinologia", tags: ["nefropatia-diabética", "ieca", "bra"] },
  { id: "fc-gen-endocrinologia-015", front: "Quais os principais achados laboratoriais da acromegalia?", back: "- IGF-1 elevado para idade e sexo.\n- GH não suprimido (<1 ng/mL) após teste de tolerância oral à glicose (TOTG) com 75g de glicose.\n- GH basal elevado (embora GH de pulso possa ser normal).", category: "endocrinologia", tags: ["acromegalia", "diagnóstico", "gh"] },
  { id: "fc-gen-endocrinologia-016", front: "Qual a dose e via de administração da vitamina D para tratamento de deficiência grave (<20 ng/mL)?", back: "- Para adultos com deficiência grave, recomenda-se colecalciferol 50.000 UI por semana, por 8-12 semanas (via oral).\n- Ou dose equivalente diária. Após normalização dos níveis, dose de manutenção de 800-2000 UI/dia.", category: "endocrinologia", tags: ["vitamina-d", "deficiência", "tratamento"] },
  { id: "fc-gen-endocrinologia-017", front: "Quais os critérios para diagnóstico de Diabetes Mellitus Gestacional (DMG) segundo a SBD?", back: "- Realizado entre 24-28 semanas de gestação (TOTG 75g).\n- Glicemia de jejum ≥ 92 mg/dL.\n- Glicemia 1h pós-TOTG ≥ 180 mg/dL.\n- Glicemia 2h pós-TOTG ≥ 153 mg/dL.\n- O diagnóstico é feito se qualquer um desses valores for atingido ou ultrapassado.", category: "endocrinologia", tags: ["dmg", "diagnóstico", "gestação"] },
  { id: "fc-gen-endocrinologia-018", front: "Cite os valores-alvo de TSH para o tratamento de hipotireoidismo em idosos (>70 anos) sem doença cardíaca.", back: "- Em idosos, o alvo de TSH é menos rigoroso devido ao risco de iatrogenia (fibrilação atrial, osteoporose).\n- TSH-alvo entre 4,0 e 6,0 mUI/L (algumas diretrizes aceitam até 7,0 mUI/L).\n- Em pacientes com comorbidades cardíacas ou muito fragilizados, pode-se tolerar TSH um pouco mais elevado.", category: "endocrinologia", tags: ["hipotireoidismo", "tsh", "idoso"] },
  { id: "fc-gen-endocrinologia-019", front: "Qual a conduta para um incidentaloma adrenal com >4 cm e/ou características de imagem suspeitas?", back: "- Indica adrenalectomia cirúrgica devido ao maior risco de malignidade.\n- Características suspeitas: densidade >10 UH na tomografia sem contraste, washout lento, margens irregulares, necrose, calcificações, crescimento rápido.", category: "endocrinologia", tags: ["incidentaloma", "adrenal", "cirurgia"] },
  { id: "fc-gen-endocrinologia-020", front: "Qual a medicação de escolha para o tratamento da Síndrome dos Ovários Policísticos (SOP) em mulheres com resistência à insulina e desejo de engravidar?", back: "- Clomifeno (citrato de clomifeno) ou letrozol para indução da ovulação.\n- Metformina pode ser adicionada para melhorar a sensibilidade à insulina e auxiliar na regularização menstrual, mas não é a primeira linha para indução da ovulação.", category: "endocrinologia", tags: ["sop", "infertilidade", "metformina"] },
  { id: "fc-gen-endocrinologia-021", front: "Qual o tratamento farmacológico para hiper tireoidismo causado pela Doença de Graves em um paciente jovem?", back: "- Tionamidas: metimazol ou propiltiouracil.\n- Metimazol é preferível devido à menor hepatotoxicidade e regime de dose mais simples.\n- Duração do tratamento geralmente de 12-18 meses, com acompanhamento e possível remissão.", category: "endocrinologia", tags: ["doença-graves", "hipertireoidismo", "tionamidas"] },
  { id: "fc-gen-endocrinologia-022", front: "Um paciente apresenta hiperprolactinemia. Quais as causas mais comuns a serem investigadas?", back: "- Adenoma hipofisário secretor de prolactina (prolactinoma).\n- Uso de medicamentos: antipsicóticos, antidepressivos (inibidores da recaptação de serotonina), anti-hipertensivos (verapamil, metildopa), opiáceos.\n- Hipotireoidismo primário (TSH elevado estimula a liberação de TRH que estimula prolactina).\n- Estresse, gestação, lactação.", category: "endocrinologia", tags: ["hiperprolactinemia", "prolactinoma", "diagnóstico"] },
  { id: "fc-gen-endocrinologia-023", front: "Quais os principais benefícios cardiovasculares dos inibidores de SGLT2 (glicoflozinas) em pacientes com DM2?", back: "- Redução de eventos cardiovasculares maiores (MACE).\n- Redução de hospitalizações por insuficiência cardíaca.\n- Benefícios renais: redução da progressão da doença renal crônica e albuminúria.\n- Redução de peso e pressão arterial.", category: "endocrinologia", tags: ["sglt2", "dm2", "cardiovascular"] },
  { id: "fc-gen-endocrinologia-024", front: "Qual a principal causa de hipocalcemia pós-tireoidectomia total e seu tratamento de emergência?", back: "- Principal causa: hipoparatireoidismo iatrogênico (remoção ou lesão das glândulas paratireoides).\n- Tratamento de emergência da hipocalcemia sintomática: Gluconato de cálcio 10% (1-2 ampolas, 10-20 mL) IV lento (em 10-20 minutos).", category: "endocrinologia", tags: ["hipocalcemia", "tireoidectomia", "calcio"] },
  { id: "fc-gen-endocrinologia-025", front: "Qual o papel do Iodo Radioativo (I-131) no tratamento da Doença de Graves?", back: "- Ablação da glândula tireoide, levando ao hipotireoidismo permanente, que é tratado com levotiroxina.\n- Indicado para pacientes com tireotoxicose persistente, doença recorrente após tionamidas, ou impossibilidade de cirurgia/recusa de tionamidas.\n- Contraindicado na gestação e lactação.", category: "endocrinologia", tags: ["iodo-radioativo", "doença-graves", "tratamento"] },
];